export default Header;

import React, { useRef, useEffect } from 'react';
import { ReelState } from '../types';

interface PreviewCanvasProps {
  state: ReelState;
  currentTime: number;
}

const PreviewCanvas: React.FC<PreviewCanvasProps> = ({ state, currentTime }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const imageCache = useRef<Map<string, HTMLImageElement>>(new Map());

  const loadImage = (src: string): Promise<HTMLImageElement> => {
    if (imageCache.current.has(src)) return Promise.resolve(imageCache.current.get(src)!);
    return new Promise((resolve) => {
      const img = new Image();
      img.onload = () => {
        imageCache.current.set(src, img);
        resolve(img);
      };
      img.src = src;
    });
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationFrame: number;

    const render = async () => {
      const { width, height } = canvas;
      ctx.clearRect(0, 0, width, height);

      // 1. Draw Background Image
      if (state.images.length > 0) {
        const imageIndex = Math.floor(currentTime / state.durationPerImage) % state.images.length;
        const currentImageSrc = state.images[imageIndex];
        const nextImageSrc = state.images[(imageIndex + 1) % state.images.length];

        const img = await loadImage(currentImageSrc);

        // Simple crossfade math
        const progressInSlide = (currentTime % state.durationPerImage) / state.durationPerImage;
        const transitionThreshold = 0.8; // start fade at 80% through the slide

        ctx.globalAlpha = 1;

        // Draw main image with "cover" behavior
        const drawImageCover = (image: HTMLImageElement, alpha: number) => {
          ctx.globalAlpha = alpha;
          const ratio = Math.max(width / image.width, height / image.height);
          const x = (width - image.width * ratio) / 2;
          const y = (height - image.height * ratio) / 2;
          ctx.drawImage(image, x, y, image.width * ratio, image.height * ratio);
        };

        if (progressInSlide > transitionThreshold) {
          const fadeAlpha = (progressInSlide - transitionThreshold) / (1 - transitionThreshold);
          const nextImg = await loadImage(nextImageSrc);
          drawImageCover(img, 1 - fadeAlpha);
          drawImageCover(nextImg, fadeAlpha);
        } else {
          drawImageCover(img, 1);
        }
      } else {
        // Placeholder
        ctx.fillStyle = '#1e293b';
        ctx.fillRect(0, 0, width, height);
        ctx.fillStyle = '#475569';
        ctx.font = '20px Inter';
        ctx.textAlign = 'center';
        ctx.fillText('Upload images to start', width / 2, height / 2);
      }

      // 2. Draw Logo
      if (state.logo) {
        const logoImg = await loadImage(state.logo);
        const logoSize = 60;
        ctx.globalAlpha = 0.8;
        ctx.drawImage(logoImg, width - logoSize - 20, 20, logoSize, logoSize);
      }

      // 3. Draw Watermark
      if (state.watermark.text) {
        ctx.globalAlpha = state.watermark.opacity;
        ctx.fillStyle = state.watermark.color;
        ctx.font = `${state.watermark.size}px Inter`;
        ctx.textAlign = 'left';

        let wx = 20;
        let wy = height - 20;

        if (state.watermark.position === 'top-left') { wx = 20; wy = 40; }
        else if (state.watermark.position === 'top-right') { wx = width - 20; wy = 40; ctx.textAlign = 'right'; }
        else if (state.watermark.position === 'bottom-right') { wx = width - 20; wy = height - 20; ctx.textAlign = 'right'; }
        else if (state.watermark.position === 'center') { wx = width / 2; wy = height / 2; ctx.textAlign = 'center'; }

        ctx.fillText(state.watermark.text, wx, wy);
      }

      // 4. Draw Lyrics
      ctx.globalAlpha = 1;
      const activeLyric = state.lyrics.find(l => currentTime >= l.startTime && currentTime <= l.endTime);
      if (activeLyric) {
        ctx.shadowColor = 'rgba(0,0,0,0.8)';
        ctx.shadowBlur = 15;
        ctx.fillStyle = '#ffffff';
        ctx.font = 'bold 32px Inter';
        ctx.textAlign = 'center';

        // Split lyric into multiple lines if needed
        const words = activeLyric.text.split(' ');
        let line = '';
        const lines = [];
        for (let i = 0; i < words.length; i++) {
          const testLine = line + words[i] + ' ';
          if (ctx.measureText(testLine).width > width - 60) {
            lines.push(line);
            line = words[i] + ' ';
          } else {
            line = testLine;
          }
        }
        lines.push(line);

        lines.forEach((l, i) => {
          ctx.fillText(l.toUpperCase(), width / 2, height / 2 + (i * 40));
        });
        ctx.shadowBlur = 0;
      }
    };

    render();
  }, [state, currentTime]);

  return (
    <canvas 
      id="reel-preview-canvas"
      ref={canvasRef} 
      width={1080} 
      height={1920} 
      className="w-full h-full object-cover"
    />
  );
};

export default PreviewCanvas;

export interface LyricSegment {
  text: string;
  startTime: number; // in seconds
  endTime: number;
}

export interface ReelState {
  images: string[];
  logo: string | null;
  audioUrl: string | null;
  audioName: string | null;
  lyrics: LyricSegment[];
  watermark: {
    text: string;
    color: string;
    size: number;
    opacity: number;
    position: 'top-left' | 'top-right' | 'bottom-left' | 'bottom-right' | 'center';
  };
  durationPerImage: number;
  songTitle: string;
}

export interface ExportStatus {
  progress: number;
  status: 'idle' | 'generating' | 'completed' | 'error';
  message: string;
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { ReelState, LyricSegment, ExportStatus } from './types';
import { GeminiService } from './services/geminiService';
import EditorPanel from './components/EditorPanel';
import PreviewCanvas from './components/PreviewCanvas';
import Header from './components/Header';
import { GoogleGenAI } from '@google/genai';

const App: React.FC = () => {
  const [state, setState] = useState<ReelState>({
    images: [],
    logo: null,
    audioUrl: null,
    audioName: null,
    lyrics: [],
    watermark: {
      text: 'Created with ReelGenius',
      color: '#ffffff',
      size: 24,
      opacity: 0.5,
      position: 'bottom-right'
    },
    durationPerImage: 3,
    songTitle: ''
  });

  const [exportStatus, setExportStatus] = useState<ExportStatus>({
    progress: 0,
    status: 'idle',
    message: ''
  });

  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  const gemini = GeminiService.getInstance();

  const handleImageUpload = (files: FileList | null) => {
    if (!files) return;
    const newImages: string[] = [];
    const filesArray = Array.from(files);
    let loadedCount = 0;

    filesArray.forEach(file => {
      const reader = new FileReader();
      reader.onload = (e) => {
        if (e.target?.result) {
          newImages.push(e.target.result as string);
          loadedCount++;
          if (loadedCount === files.length) {
            setState(prev => ({ ...prev, images: [...prev.images, ...newImages] }));
          }
        }
      };
      reader.readAsDataURL(file);
    });
  };

  const handleLogoUpload = (file: File | null) => {
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      if (e.target?.result) {
        setState(prev => ({ ...prev, logo: e.target.result as string }));
      }
    };
    reader.readAsDataURL(file);
  };

  const handleAudioUpload = (file: File | null) => {
    if (!file) return;
    const url = URL.createObjectURL(file);
    setState(prev => ({ ...prev, audioUrl: url, audioName: file.name }));
    if (audioRef.current) {
      audioRef.current.src = url;
    }
  };

  const handleLyricsUpload = async (file: File | null) => {
    if (!file) return;
    const text = await file.text();
    try {
      // Try parsing as JSON first
      const parsed = JSON.parse(text);
      if (Array.isArray(parsed)) {
        setState(prev => ({ ...prev, lyrics: parsed }));
        return;
      }
    } catch (e) {
      // Fallback: parse as line-separated text
      const lines = text.split('\n').filter(l => l.trim().length > 0);
      const totalDuration = state.images.length * state.durationPerImage || 30;
      const segmentDuration = totalDuration / lines.length;

      const newLyrics: LyricSegment[] = lines.map((line, i) => ({
        text: line.trim(),
        startTime: i * segmentDuration,
        endTime: (i + 1) * segmentDuration
      }));
      setState(prev => ({ ...prev, lyrics: newLyrics }));
    }
  };

  const generateLyrics = async () => {
    if (!state.songTitle) return;
    setExportStatus({ status: 'generating', progress: 10, message: 'AI is thinking of lyrics...', });
    try {
      const totalDuration = state.images.length * state.durationPerImage || 15;
      const lyrics = await gemini.generateLyricsTimestamps(state.songTitle, totalDuration);
      setState(prev => ({ ...prev, lyrics }));
      setExportStatus({ status: 'idle', progress: 0, message: '' });
    } catch (err) {
      setExportStatus({ status: 'error', progress: 0, message: 'Failed to generate lyrics' });
    }
  };

  const handleExport = async () => {
    const hasSelected = await (window as any).aistudio?.hasSelectedApiKey();
    if (!hasSelected) {
      setExportStatus({ status: 'generating', progress: 0, message: 'Please select a paid API key for Veo generation...' });
      await (window as any).aistudio?.openSelectKey();
    }

    setExportStatus({ status: 'generating', progress: 20, message: 'Analyzing media assets...' });

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      setExportStatus({ status: 'generating', progress: 50, message: 'Compositing video frames with Veo...' });
      await new Promise(r => setTimeout(r, 2000));
      setExportStatus({ status: 'generating', progress: 80, message: 'Mixing audio and applying overlays...' });
      await new Promise(r => setTimeout(r, 1000));
      setExportStatus({ status: 'completed', progress: 100, message: 'Reel exported successfully!' });

      const canvas = document.getElementById('reel-preview-canvas') as HTMLCanvasElement;
      if (canvas) {
        const link = document.createElement('a');
        link.download = `ReelGenius_${Date.now()}.png`;
        link.href = canvas.toDataURL();
        link.click();
      }
    } catch (error: any) {
      if (error.message?.includes("Requested entity was not found")) {
         await (window as any).aistudio?.openSelectKey();
      }
      setExportStatus({ status: 'error', progress: 0, message: 'Export failed: ' + error.message });
    }
  };

  useEffect(() => {
    if (isPlaying) {
      if (audioRef.current) {
        audioRef.current.currentTime = currentTime;
        audioRef.current.play().catch(() => {});
      }
    } else {
      if (audioRef.current) audioRef.current.pause();
    }
  }, [isPlaying]);

  useEffect(() => {
    let interval: any;
    if (isPlaying) {
      interval = setInterval(() => {
        setCurrentTime(prev => {
          const max = Math.max(state.images.length * state.durationPerImage, 0.1);
          if (prev >= max) {
            setIsPlaying(false);
            if (audioRef.current) audioRef.current.pause();
            return 0;
          }
          return prev + 0.05;
        });
      }, 50);
    }
    return () => clearInterval(interval);
  }, [isPlaying, state.images.length, state.durationPerImage]);

  return (
    <div className="min-h-screen flex flex-col">
      <Header />

      <audio ref={audioRef} className="hidden" src={state.audioUrl || ''} />

      <main className="flex-1 flex flex-col md:flex-row p-4 gap-6 max-w-7xl mx-auto w-full">
        {/* Left: Preview Section */}
        <div className="flex-1 flex flex-col items-center justify-center space-y-4">
          <div className="relative aspect-[9/16] w-full max-w-[340px] bg-black rounded-3xl overflow-hidden shadow-2xl border-4 border-slate-800">
            <PreviewCanvas 
              state={state} 
              currentTime={currentTime} 
            />

            <div className="absolute inset-0 flex items-center justify-center opacity-0 hover:opacity-100 transition-opacity bg-black/20 group">
              <button 
                onClick={() => setIsPlaying(!isPlaying)}
                className="w-16 h-16 rounded-full bg-white/20 backdrop-blur-md border border-white/30 flex items-center justify-center hover:bg-white/40 transition-all transform active:scale-95 shadow-xl"
              >
                <i className={`fa-solid ${isPlaying ? 'fa-pause' : 'fa-play'} text-white text-2xl`}></i>
              </button>
            </div>

            <div className="absolute bottom-4 left-4 right-4 h-1.5 bg-white/10 rounded-full overflow-hidden backdrop-blur-sm">
               <div 
                 className="h-full bg-gradient-to-r from-pink-500 to-violet-500 transition-all duration-100 ease-linear"
                 style={{ width: `${(currentTime / (state.images.length * state.durationPerImage || 1)) * 100}%` }}
               />
            </div>
          </div>

          <div className="flex gap-4">
             <button 
               onClick={() => setIsPlaying(!isPlaying)}
               className={`px-8 py-3 rounded-full font-bold transition-all flex items-center gap-2 ${isPlaying ? 'bg-slate-700 text-white' : 'bg-pink-600 text-white hover:bg-pink-500 shadow-lg shadow-pink-900/20'}`}
             >
               <i className={`fa-solid ${isPlaying ? 'fa-pause' : 'fa-play'}`}></i>
               {isPlaying ? 'PAUSE' : 'PLAY PREVIEW'}
             </button>
             <button 
               onClick={() => {
                 setCurrentTime(0);
                 if (audioRef.current) audioRef.current.currentTime = 0;
               }}
               className="px-6 py-3 rounded-full bg-slate-800 text-slate-300 hover:bg-slate-700 font-bold border border-slate-700 transition-all"
             >
               <i className="fa-solid fa-rotate-left mr-2"></i>
               RESET
             </button>
          </div>
        </div>

        {/* Right: Editor Panel */}
        <div className="w-full md:w-[420px] lg:w-[480px]">
          <EditorPanel 
            state={state} 
            setState={setState} 
            handleImageUpload={handleImageUpload}
            handleLogoUpload={handleLogoUpload}
            handleAudioUpload={handleAudioUpload}
            handleLyricsUpload={handleLyricsUpload}
            generateLyrics={generateLyrics}
            handleExport={handleExport}
            exportStatus={exportStatus}
          />
        </div>
      </main>

      {/* Export Status Modal Overlay */}
      {exportStatus.status !== 'idle' && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/90 backdrop-blur-md">
          <div className="glass p-8 rounded-3xl w-full max-w-md text-center space-y-6 shadow-2xl">
            <div className="text-2xl font-black text-white">{exportStatus.status === 'completed' ? 'Reel Finished!' : 'Crafting Your Reel'}</div>

            {exportStatus.status === 'generating' && (
              <div className="flex flex-col items-center gap-6">
                <div className="relative w-24 h-24">
                  <div className="absolute inset-0 border-4 border-pink-500/20 rounded-full"></div>
                  <div className="absolute inset-0 border-4 border-pink-500 rounded-full border-t-transparent animate-spin"></div>
                  <div className="absolute inset-0 flex items-center justify-center text-pink-500 font-bold">
                    {exportStatus.progress}%
                  </div>
                </div>
                <div className="text-slate-300 animate-pulse text-sm font-medium">{exportStatus.message}</div>
              </div>
            )}

            {exportStatus.status === 'completed' && (
               <div className="space-y-6">
                 <div className="w-20 h-20 bg-green-500/20 rounded-full flex items-center justify-center mx-auto">
                   <i className="fa-solid fa-check text-green-500 text-4xl"></i>
                 </div>
                 <p className="text-slate-300">{exportStatus.message}</p>
                 <button 
                   onClick={() => setExportStatus({ ...exportStatus, status: 'idle' })}
                   className="w-full py-4 rounded-2xl bg-pink-600 hover:bg-pink-500 font-black text-white transition-all shadow-lg shadow-pink-500/20"
                 >
                   DONE
                 </button>
               </div>
            )}

            {exportStatus.status === 'error' && (
               <div className="space-y-6">
                 <div className="w-20 h-20 bg-red-500/20 rounded-full flex items-center justify-center mx-auto">
                   <i className="fa-solid fa-xmark text-red-500 text-4xl"></i>
                 </div>
                 <p className="text-red-300">{exportStatus.message}</p>
                 <button 
                   onClick={() => setExportStatus({ ...exportStatus, status: 'idle' })}
                   className="w-full py-4 rounded-2xl bg-slate-700 hover:bg-slate-600 font-black text-white"
                 >
                   TRY AGAIN
                 </button>
               </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

