                      </div>
                      <button onClick={() => setState(prev => ({ ...prev, lyrics: prev.lyrics.filter((_, idx) => idx !== i) }))} className="text-slate-700 hover:text-red-500"><i className="fa-solid fa-trash text-[10px]"></i></button>
