                  </div>
                ))}
                {state.lyrics.length === 0 && <p className="text-center py-10 text-xs font-bold text-slate-600 uppercase tracking-widest">No lyrics sync'd yet</p>}
              </div>
            </section>
          </div>
        )}

        {activeTab === 'style' && (
          <div className="space-y-8 animate-in slide-in-from-right duration-300 pb-10">
            <section className="space-y-6">
              <h3 className="text-sm font-black uppercase tracking-widest text-emerald-500">Typography</h3>

              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase text-slate-500 px-1">Font Family</label>
                <div className="grid grid-cols-2 gap-2">
                  {fonts.map(font => (
                    <button 
                      key={font}
                      onClick={() => updateLyricStyle({ fontFamily: font })}
                      className={`p-3 rounded-2xl text-[10px] font-black truncate border transition-all ${
                        state.lyricStyle.fontFamily === font ? 'bg-emerald-600 border-emerald-500 text-white' : 'bg-slate-900 border-slate-800 text-slate-500'
