                   {state.logo ? <img src={state.logo} className="w-full h-full object-contain p-4" /> : (
                     <>
                      <i className="fa-solid fa-shield-halved text-2xl text-slate-700 mb-2"></i>
                      <span className="text-[9px] font-black uppercase text-slate-500">Brand Logo</span>
                     </>
                   )}
                   <input type="file" accept="image/*" className="hidden" onChange={(e) => {
                     const f = e.target.files?.[0];
                     if(f) {
                       const r = new FileReader();
                       r.onload = (ev) => setState(prev => ({ ...prev, logo: ev.target?.result as string }));
                       r.readAsDataURL(f);
                     }
                   }} />
                 </label>
                 <div className="space-y-4">
                    <div className="space-y-2">
                      <label className="text-[10px] font-black uppercase text-slate-500 px-1">TEXT LABEL</label>
                      <input type="text" value={state.watermark.text} onChange={(e) => setState(prev => ({ ...prev, watermark: { ...prev.watermark, text: e.target.value } }))} className="w-full bg-slate-900 border border-slate-800 rounded-xl px-4 py-3 text-xs font-bold text-amber-500 outline-none" />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black uppercase text-slate-500 px-1">OPACITY</label>
                      <input type="range" min="0" max="1" step="0.1" value={state.watermark.opacity} onChange={(e) => setState(prev => ({ ...prev, watermark: { ...prev.watermark, opacity: parseFloat(e.target.value) } }))} className="w-full accent-amber-500" />
                    </div>
                 </div>
               </div>
             </section>
          </div>
        )}
      </div>

      <div className="p-7 bg-slate-900/50 border-t border-slate-800">
        <button 
          onClick={handleExport}
          disabled={state.images.length === 0}
          className="w-full py-5 rounded-[2rem] bg-gradient-to-r from-pink-600 via-indigo-600 to-violet-600 text-white font-black text-lg shadow-2xl shadow-pink-600/30 active:scale-95 transition-all uppercase tracking-[0.2em] disabled:opacity-30 disabled:grayscale"
        >
          <i className="fa-solid fa-wand-magic-sparkles mr-3"></i>
          Export Reel
        </button>
      </div>
    </div>
  );
};

export default EditorPanel;

export interface LyricSegment {
  text: string;
  startTime: number; // in seconds
  endTime: number;
}

export interface ReelImage {
  url: string;
  duration: number;
}

export type LyricAnimation = 'none' | 'fade' | 'slide-up' | 'scale' | 'typewriter';

export interface LyricStyle {
  fontFamily: string;
  fontSize: number;
  lineGap: number;
  color: string;
  animation: LyricAnimation;
  verticalPosition: number; // 0 to 100 (percentage from top)
  textAlign: 'left' | 'center' | 'right';
  shadow: boolean;
}

export interface ReelState {
  images: ReelImage[];
  logo: string | null;
  audioUrl: string | null;
  audioName: string | null;
  audioDuration: number; // Actual length of the uploaded file
  audioTrim: {
    start: number;
    end: number;
  };
  lyrics: LyricSegment[];
  lyricStyle: LyricStyle;
  watermark: {
    text: string;
    color: string;
    size: number;
    opacity: number;
    position: 'top-left' | 'top-right' | 'bottom-left' | 'bottom-right' | 'center';
  };
  songTitle: string;
}

export interface ExportStatus {
  progress: number;
  status: 'idle' | 'generating' | 'completed' | 'error';
  message: string;
}

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { ReelState, LyricSegment, ExportStatus, ReelImage, LyricStyle } from './types';
import { GeminiService } from './services/geminiService';
import EditorPanel from './components/EditorPanel';
import PreviewCanvas from './components/PreviewCanvas';
import Header from './components/Header';
import { GoogleGenAI } from '@google/genai';

const App: React.FC = () => {
  const [state, setState] = useState<ReelState>({
    images: [],
    logo: null,
    audioUrl: null,
    audioName: null,
    audioDuration: 0,
    audioTrim: { start: 0, end: 15 },
    lyrics: [],
    lyricStyle: {
      fontFamily: 'Inter',
      fontSize: 48,
      lineGap: 1.2,
      color: '#ffffff',
      animation: 'fade',
      verticalPosition: 50,
      textAlign: 'center',
      shadow: true
    },
    watermark: {
      text: 'Created with ReelGenius',
      color: '#ffffff',
      size: 24,
      opacity: 0.5,
      position: 'bottom-right'
    },
    songTitle: ''
  });

  const [exportStatus, setExportStatus] = useState<ExportStatus>({
    progress: 0,
    status: 'idle',
    message: ''
  });

  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  const gemini = GeminiService.getInstance();

  const totalDuration = useMemo(() => {
    return state.images.reduce((acc, img) => acc + img.duration, 0) || 0.1;
  }, [state.images]);

  const handleImageUpload = (files: FileList | null) => {
    if (!files) return;
    const filesArray = Array.from(files);
    let loadedCount = 0;
    const newImages: ReelImage[] = [];

    filesArray.forEach(file => {
      const reader = new FileReader();
      reader.onload = (e) => {
        if (e.target?.result) {
          newImages.push({ url: e.target.result as string, duration: 3 });
          loadedCount++;
          if (loadedCount === files.length) {
            setState(prev => ({ ...prev, images: [...prev.images, ...newImages] }));
          }
        }
      };
      reader.readAsDataURL(file);
    });
  };

  const handleAudioUpload = (file: File | null) => {
    if (!file) return;
    const url = URL.createObjectURL(file);

    // Create temporary audio to get duration
    const tempAudio = new Audio(url);
    tempAudio.onloadedmetadata = () => {
      setState(prev => ({ 
        ...prev, 
        audioUrl: url, 
        audioName: file.name,
        audioDuration: tempAudio.duration,
        audioTrim: { start: 0, end: Math.min(tempAudio.duration, totalDuration) }
      }));
      if (audioRef.current) {
        audioRef.current.src = url;
      }
    };
  };

  const handleLyricsUpload = async (file: File | null) => {
    if (!file) return;
    const text = await file.text();
    try {
      const parsed = JSON.parse(text);
      if (Array.isArray(parsed)) {
        setState(prev => ({ ...prev, lyrics: parsed }));
        return;
      }
    } catch (e) {
      const lines = text.split('\n').filter(l => l.trim().length > 0);
      const segmentDuration = Math.max(totalDuration / lines.length, 1);
      const newLyrics: LyricSegment[] = lines.map((line, i) => ({
        text: line.trim(),
        startTime: i * segmentDuration,
        endTime: (i + 1) * segmentDuration
      }));
      setState(prev => ({ ...prev, lyrics: newLyrics }));
    }
  };

  const generateLyrics = async () => {
    if (!state.songTitle) return;
    setExportStatus({ status: 'generating', progress: 10, message: 'AI is thinking of lyrics...', });
    try {
      const lyrics = await gemini.generateLyricsTimestamps(state.songTitle, totalDuration);
      setState(prev => ({ ...prev, lyrics }));
      setExportStatus({ status: 'idle', progress: 0, message: '' });
    } catch (err) {
      setExportStatus({ status: 'error', progress: 0, message: 'Failed to generate lyrics' });
    }
  };

  const handleExport = async () => {
    const hasSelected = await (window as any).aistudio?.hasSelectedApiKey();
    if (!hasSelected) {
      setExportStatus({ status: 'generating', progress: 0, message: 'Please select a paid API key for Veo generation...' });
      await (window as any).aistudio?.openSelectKey();
    }

    setExportStatus({ status: 'generating', progress: 20, message: 'Analyzing assets and timing...' });

    try {
      setExportStatus({ status: 'generating', progress: 50, message: 'Rendering cinematic layers...' });
      await new Promise(r => setTimeout(r, 2000));
      setExportStatus({ status: 'completed', progress: 100, message: 'Reel exported successfully!' });

      const canvas = document.getElementById('reel-preview-canvas') as HTMLCanvasElement;
      if (canvas) {
        const link = document.createElement('a');
        link.download = `ReelGenius_${Date.now()}.png`;
        link.href = canvas.toDataURL();
        link.click();
      }
    } catch (error: any) {
      setExportStatus({ status: 'error', progress: 0, message: 'Export failed: ' + error.message });
    }
  };

  useEffect(() => {
    if (isPlaying) {
      if (audioRef.current) {
        audioRef.current.currentTime = state.audioTrim.start + currentTime;
        audioRef.current.play().catch(() => {});
      }
    } else {
      if (audioRef.current) audioRef.current.pause();
    }
  }, [isPlaying, state.audioTrim.start]);

  useEffect(() => {
    let interval: any;
    if (isPlaying) {
      interval = setInterval(() => {
        setCurrentTime(prev => {
          if (prev >= totalDuration) {
            setIsPlaying(false);
            if (audioRef.current) audioRef.current.pause();
            return 0;
          }
          return prev + 0.05;
        });
      }, 50);
    }
    return () => clearInterval(interval);
  }, [isPlaying, totalDuration]);

  return (
    <div className="min-h-screen flex flex-col">
      <Header />
      <audio ref={audioRef} className="hidden" src={state.audioUrl || ''} />
      <main className="flex-1 flex flex-col md:flex-row p-4 gap-6 max-w-7xl mx-auto w-full">
        <div className="flex-1 flex flex-col items-center justify-center space-y-4">
          <div className="relative aspect-[9/16] w-full max-w-[340px] bg-black rounded-3xl overflow-hidden shadow-2xl border-4 border-slate-800">
            <PreviewCanvas state={state} currentTime={currentTime} />
            <div className="absolute inset-0 flex items-center justify-center opacity-0 hover:opacity-100 transition-opacity bg-black/20 group">
              <button 
                onClick={() => setIsPlaying(!isPlaying)}
                className="w-16 h-16 rounded-full bg-white/20 backdrop-blur-md border border-white/30 flex items-center justify-center hover:bg-white/40 transition-all transform active:scale-95 shadow-xl"
              >
                <i className={`fa-solid ${isPlaying ? 'fa-pause' : 'fa-play'} text-white text-2xl`}></i>
              </button>
            </div>
            <div className="absolute bottom-4 left-4 right-4 h-1.5 bg-white/10 rounded-full overflow-hidden backdrop-blur-sm">
               <div 
                 className="h-full bg-gradient-to-r from-pink-500 to-violet-500 transition-all duration-100 ease-linear"
                 style={{ width: `${(currentTime / totalDuration) * 100}%` }}
               />
            </div>
          </div>
          <div className="flex gap-4">
             <button onClick={() => setIsPlaying(!isPlaying)} className={`px-8 py-3 rounded-full font-bold transition-all flex items-center gap-2 ${isPlaying ? 'bg-slate-700 text-white' : 'bg-pink-600 text-white hover:bg-pink-500 shadow-lg'}`}>
               <i className={`fa-solid ${isPlaying ? 'fa-pause' : 'fa-play'}`}></i>
               {isPlaying ? 'PAUSE' : 'PLAY PREVIEW'}
             </button>
             <button onClick={() => { setCurrentTime(0); if (audioRef.current) audioRef.current.currentTime = state.audioTrim.start; }} className="px-6 py-3 rounded-full bg-slate-800 text-slate-300 hover:bg-slate-700 font-bold border border-slate-700">
               <i className="fa-solid fa-rotate-left mr-2"></i>
               RESET
             </button>
          </div>
        </div>
        <div className="w-full md:w-[420px] lg:w-[520px]">
          <EditorPanel state={state} setState={setState} handleImageUpload={handleImageUpload} generateLyrics={generateLyrics} handleExport={handleExport} exportStatus={exportStatus} handleAudioUpload={handleAudioUpload} handleLyricsUpload={handleLyricsUpload} />
        </div>
      </main>
      {exportStatus.status !== 'idle' && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/90 backdrop-blur-md">
           <div className="glass p-8 rounded-3xl w-full max-w-md text-center space-y-6 shadow-2xl">
            <div className="text-2xl font-black text-white">{exportStatus.status === 'completed' ? 'Reel Finished!' : 'Crafting Your Reel'}</div>
            {exportStatus.status === 'generating' && (
              <div className="flex flex-col items-center gap-6">
                <div className="relative w-24 h-24">
                  <div className="absolute inset-0 border-4 border-pink-500/20 rounded-full animate-pulse"></div>
                  <div className="absolute inset-0 border-4 border-pink-500 rounded-full border-t-transparent animate-spin"></div>
                  <div className="absolute inset-0 flex items-center justify-center text-pink-500 font-bold">{exportStatus.progress}%</div>
                </div>
                <div className="text-slate-300 text-sm font-medium">{exportStatus.message}</div>
              </div>
            )}
            {exportStatus.status === 'completed' && <button onClick={() => setExportStatus(prev => ({ ...prev, status: 'idle' }))} className="w-full py-4 rounded-2xl bg-pink-600 font-black text-white uppercase tracking-widest">Done</button>}
            {exportStatus.status === 'error' && <button onClick={() => setExportStatus(prev => ({ ...prev, status: 'idle' }))} className="w-full py-4 rounded-2xl bg-slate-700 font-black text-white uppercase tracking-widest">Retry</button>}
           </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { ReelState, ExportStatus, LyricSegment, ReelImage, LyricAnimation } from '../types';

interface EditorPanelProps {
  state: ReelState;
  setState: React.Dispatch<React.SetStateAction<ReelState>>;
  handleImageUpload: (files: FileList | null) => void;
  handleAudioUpload: (file: File | null) => void;
  handleLyricsUpload: (file: File | null) => void;
  generateLyrics: () => void;
  handleExport: () => void;
  exportStatus: ExportStatus;
}

const EditorPanel: React.FC<EditorPanelProps> = ({
  state,
  setState,
  handleImageUpload,
  handleAudioUpload,
  handleLyricsUpload,
  generateLyrics,
  handleExport,
  exportStatus
}) => {
  const [activeTab, setActiveTab] = useState<'content' | 'lyrics' | 'style' | 'branding'>('content');

  const totalReelDuration = useMemo(() => {
    return state.images.reduce((acc, img) => acc + img.duration, 0) || 0;
  }, [state.images]);

  const updateImageDuration = (index: number, duration: number) => {
    setState(prev => {
      const nextImages = [...prev.images];
      nextImages[index] = { ...nextImages[index], duration: Math.max(0.1, duration) };
      return { ...prev, images: nextImages };
    });
  };

  const updateLyric = (index: number, updates: Partial<LyricSegment>) => {
    setState(prev => {
      const next = [...prev.lyrics];
      next[index] = { ...next[index], ...updates };
      return { ...prev, lyrics: next };
    });
  };

  const updateLyricStyle = (updates: Partial<typeof state.lyricStyle>) => {
    setState(prev => ({
      ...prev,
      lyricStyle: { ...prev.lyricStyle, ...updates }
    }));
  };

  const fonts = ['Inter', 'Montserrat', 'Pacifico', 'Bungee', 'Playfair Display', 'Space Mono'];
  const animations: { label: string; value: LyricAnimation }[] = [
    { label: 'None', value: 'none' },
    { label: 'Fade In', value: 'fade' },
    { label: 'Slide Up', value: 'slide-up' },
    { label: 'Scale Up', value: 'scale' },
    { label: 'Typewriter', value: 'typewriter' },
  ];

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="h-full flex flex-col glass rounded-[2.5rem] border-slate-800/50 shadow-2xl overflow-hidden">
      {/* Tabs */}
      <div className="flex p-2 bg-slate-900/50 border-b border-slate-800">
        {[
          { id: 'content', icon: 'fa-images' },
