                </div>
                <div className="flex-1 truncate">
                  <p className="text-xs font-black text-white truncate">{state.audioName || 'UPLOAD AUDIO'}</p>
                  <p className="text-[9px] text-slate-500 font-bold uppercase">{state.audioUrl ? formatTime(state.audioDuration) : 'MP3 / WAV / AAC'}</p>
