    watermark: {
      text: 'Created with ReelGenius',
      color: '#ffffff',
      size: 24,
      opacity: 0.5,
      x: 95,
      y: 95,
      textAlign: 'right'
    },
    songTitle: ''
  });

  const [exportStatus, setExportStatus] = useState<ExportStatus>({
    progress: 0,
    status: 'idle',
    message: ''
  });

  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  const gemini = GeminiService.getInstance();

  const totalDuration = useMemo(() => {
    return state.images.reduce((acc, img) => acc + img.duration, 0) || 0.1;
  }, [state.images]);

  const handleImageUpload = (files: FileList | null) => {
    if (!files) return;
    const filesArray = Array.from(files);
    let loadedCount = 0;
    const newImages: ReelImage[] = [];

    filesArray.forEach(file => {
      const reader = new FileReader();
      reader.onload = (e) => {
        if (e.target?.result) {
          newImages.push({ url: e.target.result as string, duration: 3 });
          loadedCount++;
          if (loadedCount === files.length) {
            setState(prev => ({ ...prev, images: [...prev.images, ...newImages] }));
          }
        }
      };
      reader.readAsDataURL(file);
    });
  };

  const handleAudioUpload = (file: File | null) => {
    if (!file) return;
    const url = URL.createObjectURL(file);
    const tempAudio = new Audio(url);
    tempAudio.onloadedmetadata = () => {
      setState(prev => ({ 
        ...prev, 
        audioUrl: url, 
        audioName: file.name,
        audioDuration: tempAudio.duration,
        audioTrim: { start: 0, end: Math.min(tempAudio.duration, totalDuration) }
      }));
      if (audioRef.current) audioRef.current.src = url;
    };
  };

  const handleLyricsUpload = async (file: File | null) => {
    if (!file) return;
    const text = await file.text();
    try {
      const parsed = JSON.parse(text);
      if (Array.isArray(parsed)) {
        setState(prev => ({ ...prev, lyrics: parsed }));
        return;
      }
    } catch (e) {
      const lines = text.split('\n').filter(l => l.trim().length > 0);
      const newLyrics: LyricSegment[] = lines.map((line) => ({
        text: line.trim(),
        startTime: 0,
        endTime: 0
      }));
      setState(prev => ({ ...prev, lyrics: newLyrics }));
    }
  };

  const generateLyrics = async () => {
    if (!state.songTitle) return;
    setExportStatus({ status: 'generating', progress: 10, message: 'AI is thinking of lyrics...', });
    try {
      const lyrics = await gemini.generateLyricsTimestamps(state.songTitle, totalDuration);
      setState(prev => ({ ...prev, lyrics }));
      setExportStatus({ status: 'idle', progress: 0, message: '' });
    } catch (err) {
      setExportStatus({ status: 'error', progress: 0, message: 'Failed to generate lyrics' });
    }
  };

  const handleExport = async () => {
    const hasSelected = await (window as any).aistudio?.hasSelectedApiKey();
    if (!hasSelected) {
      setExportStatus({ status: 'generating', progress: 0, message: 'Please select a paid API key for Veo generation...' });
      await (window as any).aistudio?.openSelectKey();
    }
    setExportStatus({ status: 'generating', progress: 20, message: 'Analyzing assets...' });
    try {
      setExportStatus({ status: 'generating', progress: 60, message: 'Rendering cinematic layers...' });
      await new Promise(r => setTimeout(r, 2000));
      setExportStatus({ status: 'completed', progress: 100, message: 'Reel exported successfully!' });
    } catch (error: any) {
      setExportStatus({ status: 'error', progress: 0, message: 'Export failed: ' + error.message });
    }
  };

  useEffect(() => {
    if (isPlaying) {
      if (audioRef.current) {
        audioRef.current.currentTime = state.audioTrim.start + currentTime;
        audioRef.current.play().catch(() => {});
      }
    } else {
      if (audioRef.current) audioRef.current.pause();
    }
  }, [isPlaying, state.audioTrim.start]);

  useEffect(() => {
    let interval: any;
    if (isPlaying) {
      interval = setInterval(() => {
        setCurrentTime(prev => {
          if (prev >= totalDuration) {
            setIsPlaying(false);
            if (audioRef.current) audioRef.current.pause();
            return 0;
          }
          return prev + 0.05;
        });
      }, 50);
    }
    return () => clearInterval(interval);
  }, [isPlaying, totalDuration]);

  return (
    <div className="min-h-screen flex flex-col">
      <Header />
      <audio ref={audioRef} className="hidden" src={state.audioUrl || ''} />
      <main className="flex-1 flex flex-col md:flex-row p-4 gap-6 max-w-7xl mx-auto w-full overflow-hidden">
        <div className="flex-1 flex flex-col items-center justify-center space-y-4">
          <div className="relative aspect-[9/16] w-full max-w-[340px] bg-black rounded-3xl overflow-hidden shadow-2xl border-4 border-slate-800">
            <PreviewCanvas state={state} currentTime={currentTime} />
            <div className="absolute inset-0 flex items-center justify-center opacity-0 hover:opacity-100 transition-opacity bg-black/20 group">
              <button 
                onClick={() => setIsPlaying(!isPlaying)}
                className="w-16 h-16 rounded-full bg-white/20 backdrop-blur-md border border-white/30 flex items-center justify-center hover:bg-white/40 transition-all transform active:scale-95 shadow-xl"
              >
                <i className={`fa-solid ${isPlaying ? 'fa-pause' : 'fa-play'} text-white text-2xl`}></i>
              </button>
            </div>
            <div className="absolute bottom-4 left-4 right-4 h-1.5 bg-white/10 rounded-full overflow-hidden backdrop-blur-sm">
               <div 
                 className="h-full bg-gradient-to-r from-pink-500 to-violet-500 transition-all duration-100 ease-linear"
                 style={{ width: `${(currentTime / totalDuration) * 100}%` }}
               />
            </div>
          </div>
          <div className="flex gap-4">
             <button onClick={() => setIsPlaying(!isPlaying)} className={`px-8 py-3 rounded-full font-bold transition-all flex items-center gap-2 ${isPlaying ? 'bg-slate-700 text-white' : 'bg-pink-600 text-white hover:bg-pink-500 shadow-lg'}`}>
               <i className={`fa-solid ${isPlaying ? 'fa-pause' : 'fa-play'}`}></i>
               {isPlaying ? 'PAUSE' : 'PLAY PREVIEW'}
             </button>
             <button onClick={() => { setCurrentTime(0); if (audioRef.current) audioRef.current.currentTime = state.audioTrim.start; }} className="px-6 py-3 rounded-full bg-slate-800 text-slate-300 hover:bg-slate-700 font-bold border border-slate-700">
               <i className="fa-solid fa-rotate-left mr-2"></i>
               RESET
             </button>
          </div>
        </div>
        <div className="w-full md:w-[420px] lg:w-[520px] h-[calc(100vh-140px)]">
          <EditorPanel state={state} setState={setState} handleImageUpload={handleImageUpload} generateLyrics={generateLyrics} handleExport={handleExport} exportStatus={exportStatus} handleAudioUpload={handleAudioUpload} handleLyricsUpload={handleLyricsUpload} currentTime={currentTime} />
        </div>
      </main>
      {exportStatus.status !== 'idle' && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/90 backdrop-blur-md">
           <div className="glass p-8 rounded-3xl w-full max-w-md text-center space-y-6 shadow-2xl">
            <div className="text-2xl font-black text-white">{exportStatus.status === 'completed' ? 'Reel Finished!' : 'Crafting Your Reel'}</div>
            {exportStatus.status === 'generating' && (
              <div className="flex flex-col items-center gap-6">
                <div className="relative w-24 h-24">
                  <div className="absolute inset-0 border-4 border-pink-500/20 rounded-full animate-pulse"></div>
                  <div className="absolute inset-0 border-4 border-pink-500 rounded-full border-t-transparent animate-spin"></div>
                  <div className="absolute inset-0 flex items-center justify-center text-pink-500 font-bold">{exportStatus.progress}%</div>
                </div>
                <div className="text-slate-300 text-sm font-medium">{exportStatus.message}</div>
              </div>
            )}
            {exportStatus.status === 'completed' && <button onClick={() => setExportStatus(prev => ({ ...prev, status: 'idle' }))} className="w-full py-4 rounded-2xl bg-pink-600 font-black text-white uppercase tracking-widest">Done</button>}
            {exportStatus.status === 'error' && <button onClick={() => setExportStatus(prev => ({ ...prev, status: 'idle' }))} className="w-full py-4 rounded-2xl bg-slate-700 font-black text-white uppercase tracking-widest">Retry</button>}
           </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { ReelState, ExportStatus, LyricSegment, ReelImage, LyricAnimation } from '../types';

interface EditorPanelProps {
  state: ReelState;
  setState: React.Dispatch<React.SetStateAction<ReelState>>;
  handleImageUpload: (files: FileList | null) => void;
  handleAudioUpload: (file: File | null) => void;
  handleLyricsUpload: (file: File | null) => void;
  generateLyrics: () => void;
  handleExport: () => void;
  exportStatus: ExportStatus;
  currentTime: number;
}

const EditorPanel: React.FC<EditorPanelProps> = ({
  state,
  setState,
  handleImageUpload,
  handleAudioUpload,
  handleLyricsUpload,
  generateLyrics,
  handleExport,
  exportStatus,
  currentTime
}) => {
  const [activeTab, setActiveTab] = useState<'content' | 'lyrics' | 'style' | 'branding'>('content');

  const totalReelDuration = useMemo(() => {
    return state.images.reduce((acc, img) => acc + img.duration, 0) || 0;
  }, [state.images]);

  const updateImageDuration = (index: number, duration: number) => {
    setState(prev => {
      const nextImages = [...prev.images];
      nextImages[index] = { ...nextImages[index], duration: Math.max(0.1, duration) };
      return { ...prev, images: nextImages };
    });
  };

  const updateLyric = (index: number, updates: Partial<LyricSegment>) => {
    setState(prev => {
      const next = [...prev.lyrics];
      next[index] = { ...next[index], ...updates };
      return { ...prev, lyrics: next };
    });
  };

  const updateLyricStyle = (updates: Partial<typeof state.lyricStyle>) => {
    setState(prev => ({
      ...prev,
      lyricStyle: { ...prev.lyricStyle, ...updates }
    }));
  };

  const updateWatermark = (updates: Partial<typeof state.watermark>) => {
    setState(prev => ({
      ...prev,
      watermark: { ...prev.watermark, ...updates }
    }));
  };

  const updateLogoPosition = (updates: Partial<typeof state.logoPosition>) => {
    setState(prev => ({
      ...prev,
      logoPosition: { ...prev.logoPosition, ...updates }
    }));
  };

  const teluguFonts = ['Hind Guntur', 'Ramabhadra', 'Gidugu', 'Gurajada', 'Suranna', 'NTR', 'Tenali Ramakrishna'];
  const latinFonts = ['Inter', 'Montserrat', 'Pacifico', 'Bungee', 'Playfair Display', 'Space Mono'];
  const animations: { label: string; value: LyricAnimation }[] = [
    { label: 'None', value: 'none' },
    { label: 'Fade', value: 'fade' },
    { label: 'Slide', value: 'slide-up' },
    { label: 'Zoom', value: 'scale' },
    { label: 'Type', value: 'typewriter' },
    { label: 'Neon', value: 'glow-pulse' },
    { label: 'Float', value: 'float' },
  ];

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    const ms = Math.floor((seconds % 1) * 10);
    return `${mins}:${secs.toString().padStart(2, '0')}.${ms}`;
  };

  return (
    <div className="h-full flex flex-col glass rounded-[2.5rem] border-slate-800/50 shadow-2xl overflow-hidden">
      {/* Tab Navigation */}
      <div className="flex p-2 bg-slate-900/50 border-b border-slate-800">
        {[
          { id: 'content', icon: 'fa-images' },
          { id: 'lyrics', icon: 'fa-clock' },
          { id: 'style', icon: 'fa-wand-magic-sparkles' },
          { id: 'branding', icon: 'fa-copyright' }
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex-1 py-3 rounded-2xl flex flex-col items-center gap-1 transition-all ${
              activeTab === tab.id ? 'bg-pink-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'
            }`}
          >
            <i className={`fa-solid ${tab.icon} text-sm`}></i>
            <span className="text-[9px] font-black uppercase tracking-tighter">{tab.id}</span>
          </button>
        ))}
      </div>

      <div className="flex-1 overflow-y-auto p-7 space-y-8 custom-scrollbar">
        {activeTab === 'content' && (
          <div className="space-y-6 animate-in fade-in duration-300">
            <section className="space-y-4">
              <h3 className="text-sm font-black uppercase tracking-widest text-pink-500">Timeline Media</h3>
              <div className="grid grid-cols-2 gap-4">
                {state.images.map((img, idx) => (
                  <div key={idx} className="bg-slate-900/40 rounded-3xl p-3 border border-slate-800/50 group">
                    <div className="aspect-[4/5] rounded-2xl overflow-hidden relative mb-3">
                      <img src={img.url} className="w-full h-full object-cover" />
                      <button onClick={() => setState(prev => ({ ...prev, images: prev.images.filter((_, i) => i !== idx) }))} className="absolute top-2 right-2 w-8 h-8 bg-red-500 rounded-full text-white opacity-0 group-hover:opacity-100 transition-opacity"><i className="fa-solid fa-trash-can text-xs"></i></button>
                    </div>
                    <div className="flex items-center gap-3">
                      <i className="fa-solid fa-stopwatch text-slate-500 text-xs"></i>
                      <input type="number" step="0.1" value={img.duration} onChange={(e) => updateImageDuration(idx, parseFloat(e.target.value))} className="w-full bg-slate-800 border-none rounded-xl text-xs font-bold text-pink-400 p-2 outline-none" />
                    </div>
                  </div>
                ))}
                <label className="aspect-[4/5] rounded-3xl border-2 border-dashed border-slate-800 flex flex-col items-center justify-center cursor-pointer hover:border-pink-500/50 hover:bg-pink-500/5 transition-all">
                  <i className="fa-solid fa-plus-circle text-2xl text-slate-600 mb-2"></i>
                  <span className="text-[10px] font-black uppercase text-slate-500 text-center px-4">Add Images</span>
                  <input type="file" multiple accept="image/*" className="hidden" onChange={(e) => handleImageUpload(e.target.files)} />
                </label>
              </div>
            </section>

            <section className="space-y-4">
              <h3 className="text-sm font-black uppercase tracking-widest text-violet-500">Audio Sync</h3>
              <label className="w-full p-5 bg-slate-900 border border-slate-800 rounded-[1.5rem] flex items-center gap-4 cursor-pointer hover:bg-slate-800 transition-all border-dashed">
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center ${state.audioUrl ? 'bg-violet-600' : 'bg-slate-800'}`}>
                  <i className={`fa-solid ${state.audioUrl ? 'fa-music' : 'fa-upload'}`}></i>
                </div>
                <div className="flex-1 truncate">
                  <p className="text-xs font-black text-white truncate">{state.audioName || 'UPLOAD SONG'}</p>
                </div>
                <input type="file" accept="audio/*" className="hidden" onChange={(e) => handleAudioUpload(e.target.files?.[0] || null)} />
              </label>
              {state.audioUrl && (
                <div className="bg-slate-900/60 p-5 rounded-3xl border border-slate-800 space-y-4">
                  <div className="flex justify-between text-[10px] font-black uppercase text-slate-500 tracking-widest"><span>START AT</span><span className="text-violet-400">{formatTime(state.audioTrim.start)}</span></div>
                  <input type="range" min="0" max={Math.max(0, state.audioDuration - totalReelDuration)} step="0.1" value={state.audioTrim.start} onChange={(e) => setState(prev => ({ ...prev, audioTrim: { ...prev.audioTrim, start: parseFloat(e.target.value) } }))} className="w-full h-1.5 accent-violet-500 appearance-none bg-slate-800 rounded-full" />
                </div>
              )}
            </section>
          </div>
        )}

        {activeTab === 'lyrics' && (
          <div className="space-y-8 animate-in slide-in-from-right duration-300">
            <section className="space-y-5">
              <h3 className="text-sm font-black uppercase tracking-widest text-indigo-500">Lyric Sync Mode</h3>
              <p className="text-[11px] text-slate-400 italic">Use <b>"SET START"</b> and <b>"SET END"</b> buttons while playing the video to sync.</p>
              <div className="flex gap-2">
                <input 
                  type="text" 
                  placeholder="Paste lyrics line by line..." 
                  className="flex-1 bg-slate-900 border border-slate-800 rounded-2xl px-5 py-4 text-xs font-bold outline-none focus:border-indigo-500 transition-all"
                  value={state.songTitle}
                  onChange={(e) => setState(prev => ({ ...prev, songTitle: e.target.value }))}
                />
                <button onClick={generateLyrics} disabled={!state.songTitle} className="px-6 rounded-2xl bg-indigo-600 hover:bg-indigo-500 text-[10px] font-black uppercase text-white shadow-lg">Magic Sync</button>
              </div>
            </section>

            <section className="space-y-3">
              {state.lyrics.map((l, i) => (
                <div key={i} className={`bg-slate-900/60 p-5 rounded-3xl border transition-all ${currentTime >= l.startTime && currentTime <= l.endTime ? 'border-pink-500 shadow-lg shadow-pink-500/10' : 'border-slate-800'}`}>
                  <textarea 
                    value={l.text}
                    onChange={(e) => updateLyric(i, { text: e.target.value })}
                    className="w-full bg-transparent border-none text-xs font-black text-white resize-none h-12 outline-none p-0 custom-scrollbar"
                    style={{ fontFamily: state.lyricStyle.fontFamily }}
                  />
                  <div className="flex items-center gap-2 mt-4">
                    <button 
                      onClick={() => updateLyric(i, { startTime: currentTime })}
                      className={`flex-1 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${l.startTime > 0 ? 'bg-green-600/20 text-green-400 border border-green-600/30' : 'bg-slate-800 text-slate-400 hover:bg-indigo-600 hover:text-white'}`}
                    >
                      {l.startTime > 0 ? `In: ${l.startTime.toFixed(1)}s` : 'Set Start'}
                    </button>
                    <button 
                      onClick={() => updateLyric(i, { endTime: currentTime })}
                      className={`flex-1 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${l.endTime > 0 ? 'bg-red-600/20 text-red-400 border border-red-600/30' : 'bg-slate-800 text-slate-400 hover:bg-pink-600 hover:text-white'}`}
                    >
                      {l.endTime > 0 ? `Out: ${l.endTime.toFixed(1)}s` : 'Set End'}
                    </button>
                    <button onClick={() => setState(prev => ({ ...prev, lyrics: prev.lyrics.filter((_, idx) => idx !== i) }))} className="p-2 text-slate-700 hover:text-red-500"><i className="fa-solid fa-trash-can text-xs"></i></button>
                  </div>
                </div>
              ))}
              <button 
                onClick={() => setState(prev => ({ ...prev, lyrics: [...prev.lyrics, { text: 'New Lyric Line', startTime: 0, endTime: 0 }] }))}
                className="w-full py-4 border-2 border-dashed border-slate-800 rounded-3xl text-slate-500 font-black uppercase text-xs hover:bg-slate-800 transition-all"
              >
                + Add Custom Line
              </button>
            </section>
          </div>
        )}

        {activeTab === 'style' && (
          <div className="space-y-8 animate-in slide-in-from-right duration-300 pb-10">
            <section className="space-y-6">
              <h3 className="text-sm font-black uppercase tracking-widest text-emerald-500">Typography & Effects</h3>

              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase text-slate-500 px-1">Font Family</label>
                <div className="space-y-4">
                  <div>
                    <p className="text-[9px] font-bold text-slate-600 mb-2 uppercase tracking-tighter">Telugu Fonts</p>
                    <div className="grid grid-cols-2 gap-2">
                      {teluguFonts.map(font => (
                        <button key={font} onClick={() => updateLyricStyle({ fontFamily: font })} className={`p-3 rounded-2xl text-[10px] font-black truncate border transition-all ${state.lyricStyle.fontFamily === font ? 'bg-emerald-600 border-emerald-500 text-white shadow-md' : 'bg-slate-900 border-slate-800 text-slate-500'}`} style={{ fontFamily: font }}>{font}</button>
                      ))}
                    </div>
                  </div>
                  <div>
                    <p className="text-[9px] font-bold text-slate-600 mb-2 uppercase tracking-tighter">Modern Fonts</p>
                    <div className="grid grid-cols-2 gap-2">
                      {latinFonts.map(font => (
                        <button key={font} onClick={() => updateLyricStyle({ fontFamily: font })} className={`p-3 rounded-2xl text-[10px] font-black truncate border transition-all ${state.lyricStyle.fontFamily === font ? 'bg-emerald-600 border-emerald-500 text-white shadow-md' : 'bg-slate-900 border-slate-800 text-slate-500'}`} style={{ fontFamily: font }}>{font}</button>
                      ))}
                    </div>
                  </div>
                </div>
              </div>

              <div className="space-y-4 pt-4 border-t border-slate-800/50">
                <div className="flex items-center justify-between">
                  <label className="text-[10px] font-black uppercase text-slate-500">Base Text Color</label>
                  <input type="color" value={state.lyricStyle.color} onChange={(e) => updateLyricStyle({ color: e.target.value })} className="w-10 h-10 rounded-xl bg-slate-900 border-none cursor-pointer" />
                </div>

                <div className="space-y-4">
                  <div className="flex items-center justify-between">
                    <label className="text-[10px] font-black uppercase text-slate-500">Gradient Overlay</label>
                    <button onClick={() => updateLyricStyle({ gradient: !state.lyricStyle.gradient })} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase border transition-all ${state.lyricStyle.gradient ? 'bg-emerald-600 text-white' : 'bg-slate-900 text-slate-500'}`}>{state.lyricStyle.gradient ? 'ON' : 'OFF'}</button>
                  </div>
                  {state.lyricStyle.gradient && (
                    <div className="grid grid-cols-2 gap-4 animate-in slide-in-from-top-2">
                       <div className="space-y-2">
                          <label className="text-[8px] font-black uppercase text-slate-600">Start Color</label>
                          <input type="color" value={state.lyricStyle.gradientColors[0]} onChange={(e) => updateLyricStyle({ gradientColors: [e.target.value, state.lyricStyle.gradientColors[1]] })} className="w-full h-8 rounded-lg bg-slate-800 border-none cursor-pointer" />
                       </div>
                       <div className="space-y-2">
                          <label className="text-[8px] font-black uppercase text-slate-600">End Color</label>
                          <input type="color" value={state.lyricStyle.gradientColors[1]} onChange={(e) => updateLyricStyle({ gradientColors: [state.lyricStyle.gradientColors[0], e.target.value] })} className="w-full h-8 rounded-lg bg-slate-800 border-none cursor-pointer" />
                       </div>
                    </div>
                  )}
                </div>
              </div>

              <div className="space-y-3 pt-4 border-t border-slate-800/50">
                <div className="flex justify-between text-[10px] font-black uppercase text-slate-500"><span>Neon Glow Power</span><span className="text-emerald-500">{state.lyricStyle.glowIntensity}</span></div>
                <div className="flex gap-4 items-center">
                   <input type="color" value={state.lyricStyle.glowColor} onChange={(e) => updateLyricStyle({ glowColor: e.target.value })} className="w-10 h-10 rounded-xl bg-slate-900 border-none cursor-pointer" />
                   <input type="range" min="0" max="50" value={state.lyricStyle.glowIntensity} onChange={(e) => updateLyricStyle({ glowIntensity: parseInt(e.target.value) })} className="flex-1 accent-emerald-500" />
                </div>
              </div>
            </section>

            <section className="space-y-6">
              <h3 className="text-sm font-black uppercase tracking-widest text-emerald-500">Layout & Size</h3>
              <div className="space-y-6">
                 <div className="space-y-2">
                    <div className="flex justify-between text-[10px] font-black uppercase text-slate-500"><span>Font Size</span><span className="text-emerald-500">{state.lyricStyle.fontSize}px</span></div>
