import { GoogleGenAI, Type } from "@google/genai";
import { LyricSegment } from "../types";

export class GeminiService {
  private static instance: GeminiService;

  private constructor() {}

  public static getInstance(): GeminiService {
    if (!GeminiService.instance) {
      GeminiService.instance = new GeminiService();
    }
    return GeminiService.instance;
  }

  private getClient() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  async generateLyricsTimestamps(songTitle: string, totalDuration: number): Promise<LyricSegment[]> {
    const ai = this.getClient();
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Generate a short list of catchy lyrics or captions ONLY in Telugu language (తెలుగు) with relevant emojis for a video about "${songTitle}". 
      IMPORTANT: 
      1. Use ONLY Telugu script. Do not use English words or Hinglish/Telugish.
      2. Include colorful and relevant emojis in every line.
      3. Return them as JSON with startTime and endTime in seconds. 
      4. Total duration of the song is ${totalDuration} seconds. 
      5. Distribute the lyrics evenly throughout the duration.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              text: { type: Type.STRING },
              startTime: { type: Type.NUMBER },
              endTime: { type: Type.NUMBER },
            },
            required: ["text", "startTime", "endTime"],
          },
        },
      },
    });

    try {
      return JSON.parse(response.text || "[]");
    } catch (e) {
      console.error("Failed to parse lyrics JSON", e);
      return [];
    }
  }

  async generateEnhancementPrompt(images: string[]): Promise<string> {
    const ai = this.getClient();
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `I have a series of images for a reel. Generate a cinematic prompt for professional video transitions and overlays.`,
    });
    return response.text || "Cinematic smooth professional transitions for social media reels.";
  }
}

import React, { useState, useMemo } from 'react';
import { ReelState, ExportStatus, LyricSegment, ReelImage, LyricAnimation } from '../types';

interface EditorPanelProps {
  state: ReelState;
  setState: React.Dispatch<React.SetStateAction<ReelState>>;
  handleImageUpload: (files: FileList | null) => void;
  handleAudioUpload: (file: File | null) => void;
  handleLyricsUpload: (file: File | null) => void;
  generateLyrics: () => void;
  handleExport: () => void;
  exportStatus: ExportStatus;
  currentTime: number;
}

const EditorPanel: React.FC<EditorPanelProps> = ({
  state,
  setState,
  handleImageUpload,
  handleAudioUpload,
  handleLyricsUpload,
  generateLyrics,
  handleExport,
  exportStatus,
  currentTime
}) => {
  const [activeTab, setActiveTab] = useState<'content' | 'lyrics' | 'style' | 'branding'>('content');

  const totalReelDuration = useMemo(() => {
    return state.images.reduce((acc, img) => acc + img.duration, 0) || 0;
  }, [state.images]);

  const updateImageDuration = (index: number, duration: number) => {
    setState(prev => {
      const nextImages = [...prev.images];
      nextImages[index] = { ...nextImages[index], duration: Math.max(0.1, duration) };
      return { ...prev, images: nextImages };
    });
  };

  const updateLyric = (index: number, updates: Partial<LyricSegment>) => {
    setState(prev => {
      const next = [...prev.lyrics];
      next[index] = { ...next[index], ...updates };
      return { ...prev, lyrics: next };
    });
  };

  const updateLyricStyle = (updates: Partial<typeof state.lyricStyle>) => {
    setState(prev => ({
      ...prev,
      lyricStyle: { ...prev.lyricStyle, ...updates }
    }));
  };

  const updateWatermark = (updates: Partial<typeof state.watermark>) => {
    setState(prev => ({
      ...prev,
      watermark: { ...prev.watermark, ...updates }
    }));
  };

