    { label: 'Slide', value: 'slide-up', icon: 'fa-arrow-up' },
    { label: 'Zoom', value: 'scale', icon: 'fa-expand' },
    { label: 'Type', value: 'typewriter', icon: 'fa-keyboard' },
    { label: 'Neon', value: 'glow-pulse', icon: 'fa-bolt' },
