                     <div className="space-y-2">
                        <label className="text-[10px] font-black uppercase text-slate-500">Move Y (%)</label>
                        <input type="range" min="0" max="100" value={state.watermark.y} onChange={(e) => updateWatermark({ y: parseInt(e.target.value) })} className="w-full accent-amber-500" />
                     </div>
                  </div>

                  <div className="space-y-2">
                    <div className="flex justify-between text-[10px] font-black uppercase text-slate-500"><span>Opacity</span><span className="text-amber-500">{Math.round(state.watermark.opacity * 100)}%</span></div>
                    <input type="range" min="0" max="1" step="0.1" value={state.watermark.opacity} onChange={(e) => updateWatermark({ opacity: parseFloat(e.target.value) })} className="w-full accent-amber-500" />
                  </div>

                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-slate-500">Text Align</label>
                    <div className="flex gap-2">
                      {['left', 'center', 'right'].map(align => (
                        <button key={align} onClick={() => updateWatermark({ textAlign: align as any })} className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase border transition-all ${state.watermark.textAlign === align ? 'bg-amber-600 border-amber-500 text-white shadow-md' : 'bg-slate-900 border-slate-800 text-slate-500'}`}>{align}</button>
                      ))}
                    </div>
                  </div>
               </div>
             </section>
          </div>
        )}
      </div>

      <div className="p-7 bg-slate-900/50 border-t border-slate-800">
        <button 
          onClick={handleExport}
          disabled={state.images.length === 0}
          className="w-full py-5 rounded-[2.5rem] bg-gradient-to-r from-pink-600 via-indigo-600 to-violet-600 text-white font-black text-lg shadow-2xl hover:scale-[1.02] active:scale-95 transition-all uppercase tracking-[0.2em] disabled:opacity-30"
        >
          Create Final Reel
        </button>
      </div>
    </div>
  );
};

