import React, { useState, useRef, useEffect, useMemo } from 'react';
import { ReelState, LyricSegment, ExportStatus, ReelMedia, LyricStyle } from './types';
import { GeminiService } from './services/geminiService';
import EditorPanel from './components/EditorPanel';
import PreviewCanvas from './components/PreviewCanvas';
import Header from './components/Header';

const App: React.FC = () => {
  const [state, setState] = useState<ReelState>({
    images: [],
    logo: null,
    logoPosition: { x: 85, y: 10, size: 120 },
    audioUrl: null,
    audioName: null,
    audioDuration: 0,
    audioTrim: { start: 0, end: 15 },
    lyrics: [],
    lyricStyle: {
      fontFamily: 'Ramabhadra',
      fontSize: 84,
      lineGap: 1.3,
      color: '#ffffff',
      animation: 'slide-up',
      verticalPosition: 50,
      textAlign: 'center',
      shadow: true,
      glowColor: '#ec4899',
      glowIntensity: 20,
      gradient: true,
      gradientColors: ['#ffffff', '#f472b6'],
      stroke: true,
      strokeColor: '#000000',
      strokeWidth: 5
    },
    watermark: {
      text: 'Created with ReelGenius',
      color: '#ffffff',
      size: 28,
      opacity: 0.7,
      x: 50,
      y: 90,
      textAlign: 'center'
    },
    songTitle: ''
  });

  const [exportStatus, setExportStatus] = useState<ExportStatus>({
    progress: 0,
    status: 'idle',
    message: ''
  });

  const [isPlaying, setIsPlaying] = useState(false);
  const [isExporting, setIsExporting] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const recordedChunksRef = useRef<Blob[]>([]);

  const gemini = GeminiService.getInstance();

  const totalDuration = useMemo(() => {
    return state.images.reduce((acc, img) => acc + img.duration, 0) || 0.1;
  }, [state.images]);

  const handleMediaUpload = async (files: FileList | null) => {
    if (!files) return;
    const filesArray = Array.from(files);
    const newMediaItems: ReelMedia[] = [];

    for (const file of filesArray) {
      if (file.type.startsWith('image/')) {
        const reader = new FileReader();
        const promise = new Promise<void>((resolve) => {
          reader.onload = (e) => {
            if (e.target?.result) {
              newMediaItems.push({ 
                url: e.target.result as string, 
                type: 'image',
                duration: 3,
                transition: 'zoom-in'
              });
            }
            resolve();
          };
          reader.readAsDataURL(file);
        });
        await promise;
      } else if (file.type.startsWith('video/')) {
        const url = URL.createObjectURL(file);
        const tempVideo = document.createElement('video');
        tempVideo.src = url;
        const promise = new Promise<void>((resolve) => {
          tempVideo.onloadedmetadata = () => {
            const vidDuration = tempVideo.duration;
            newMediaItems.push({
              url: url,
              type: 'video',
              duration: vidDuration, // Completely applied as requested
              originalDuration: vidDuration,
              transition: 'fade'
            });
            resolve();
          };
        });
        await promise;
      }
    }

    setState(prev => ({ ...prev, images: [...prev.images, ...newMediaItems] }));
  };

  const handleAudioUpload = (file: File | null) => {
    if (!file) return;
    const url = URL.createObjectURL(file);
    const tempAudio = new Audio(url);
    tempAudio.onloadedmetadata = () => {
      setState(prev => ({ 
        ...prev, 
        audioUrl: url, 
        audioName: file.name,
        audioDuration: tempAudio.duration,
        audioTrim: { start: 0, end: Math.min(tempAudio.duration, totalDuration) }
      }));
      if (audioRef.current) audioRef.current.src = url;
    };
  };

  const generateLyrics = async () => {
    if (!state.songTitle) return;
    setExportStatus({ status: 'generating', progress: 10, message: 'AI is thinking of Telugu lyrics...', });
    try {
      const lyrics = await gemini.generateLyricsTimestamps(state.songTitle, totalDuration);
      setState(prev => ({ ...prev, lyrics }));
      setExportStatus({ status: 'idle', progress: 0, message: '' });
    } catch (err) {
      setExportStatus({ status: 'error', progress: 0, message: 'Failed to generate Telugu lyrics' });
    }
  };

  const handleExport = async () => {
    if (state.images.length === 0) return;
    setIsExporting(true);
    setExportStatus({ status: 'generating', progress: 0, message: 'Preparing high-def recorder...' });

    setCurrentTime(0);
    recordedChunksRef.current = [];

    const canvas = document.getElementById('reel-preview-canvas') as HTMLCanvasElement;
    if (!canvas) {
      setExportStatus({ status: 'error', progress: 0, message: 'Canvas engine not found.' });
      return;
    }

    const stream = canvas.captureStream(30); 
    if (audioRef.current && (audioRef.current as any).captureStream) {
      const audioStream = (audioRef.current as any).captureStream();
      const audioTrack = audioStream.getAudioTracks()[0];
      if (audioTrack) stream.addTrack(audioTrack);
    }

    const recorder = new MediaRecorder(stream, { mimeType: 'video/webm;codecs=vp9,opus' });
    recorder.ondataavailable = (e) => { if (e.data.size > 0) recordedChunksRef.current.push(e.data); };
    recorder.onstop = () => {
      const blob = new Blob(recordedChunksRef.current, { type: 'video/webm' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `telugu-reel-${Date.now()}.webm`;
      a.click();
      setExportStatus({ status: 'completed', progress: 100, message: 'Cinema-quality Reel downloaded!' });
      setIsExporting(false);
      setIsPlaying(false);
    };

    mediaRecorderRef.current = recorder;
    recorder.start();
    setIsPlaying(true);
  };

  useEffect(() => {
    if (isPlaying) {
      if (audioRef.current) {
        audioRef.current.currentTime = state.audioTrim.start + currentTime;
        audioRef.current.play().catch(() => {});
      }
    } else {
      if (audioRef.current) audioRef.current.pause();
    }
  }, [isPlaying, state.audioTrim.start]);

  useEffect(() => {
    let interval: any;
    if (isPlaying) {
      interval = setInterval(() => {
        setCurrentTime(prev => {
          const nextTime = prev + 0.05;
          if (isExporting) {
             const progress = Math.min(100, Math.floor((nextTime / totalDuration) * 100));
             setExportStatus(s => ({ ...s, progress, message: `Capturing frames: ${progress}%` }));
          }
          if (nextTime >= totalDuration) {
            setIsPlaying(false);
            if (audioRef.current) audioRef.current.pause();
            if (isExporting && mediaRecorderRef.current) mediaRecorderRef.current.stop();
            return totalDuration;
          }
          return nextTime;
        });
      }, 50);
    }
    return () => clearInterval(interval);
  }, [isPlaying, totalDuration, isExporting]);

  return (
    <div className="min-h-screen flex flex-col">
      <Header />
      <audio ref={audioRef} className="hidden" src={state.audioUrl || ''} crossOrigin="anonymous" />
      <main className="flex-1 flex flex-col md:flex-row p-4 gap-6 max-w-7xl mx-auto w-full overflow-hidden">
        <div className="flex-1 flex flex-col items-center justify-center space-y-4">
          <div className="relative aspect-[9/16] w-full max-w-[340px] bg-black rounded-3xl overflow-hidden shadow-2xl border-4 border-slate-800 group">
            <PreviewCanvas state={state} currentTime={currentTime} isPlaying={isPlaying} />
            <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity bg-black/30">
              {!isExporting && (
                <button onClick={() => setIsPlaying(!isPlaying)} className="w-16 h-16 rounded-full bg-white/20 backdrop-blur-md border border-white/30 flex items-center justify-center hover:bg-white/40 transition-all transform active:scale-95 shadow-xl">
                  <i className={`fa-solid ${isPlaying ? 'fa-pause' : 'fa-play'} text-white text-2xl`}></i>
                </button>
              )}
            </div>
            {isExporting && (
               <div className="absolute top-4 left-4 flex items-center gap-2 bg-red-600 px-3 py-1 rounded-full animate-pulse shadow-lg">
                 <div className="w-2 h-2 bg-white rounded-full"></div>
                 <span className="text-[10px] font-black text-white uppercase tracking-widest">RECORDING LIVE</span>
               </div>
            )}
            <div className="absolute bottom-4 left-4 right-4 h-1.5 bg-white/10 rounded-full overflow-hidden backdrop-blur-sm">
               <div className="h-full bg-gradient-to-r from-pink-500 to-violet-500 transition-all duration-100 ease-linear" style={{ width: `${(currentTime / totalDuration) * 100}%` }} />
            </div>
          </div>
          <div className="flex gap-4">
             <button disabled={isExporting} onClick={() => setIsPlaying(!isPlaying)} className={`px-8 py-3 rounded-full font-bold transition-all flex items-center gap-2 ${isPlaying ? 'bg-slate-700 text-white' : 'bg-pink-600 text-white hover:bg-pink-500 shadow-lg shadow-pink-500/30'} disabled:opacity-50`}>
               <i className={`fa-solid ${isPlaying ? 'fa-pause' : 'fa-play'}`}></i> {isPlaying ? 'PAUSE' : 'PLAY REEL'}
             </button>
             <button disabled={isExporting} onClick={() => { setCurrentTime(0); if (audioRef.current) audioRef.current.currentTime = state.audioTrim.start; }} className="px-6 py-3 rounded-full bg-slate-800 text-slate-300 hover:bg-slate-700 font-bold border border-slate-700 disabled:opacity-50">
               <i className="fa-solid fa-rotate-left mr-2"></i> RESTART
             </button>
          </div>
        </div>
        <div className="w-full md:w-[420px] lg:w-[520px] h-[calc(100vh-140px)]">
          <EditorPanel 
            state={state} 
            setState={setState} 
            handleImageUpload={handleMediaUpload} 
            generateLyrics={generateLyrics} 
            handleExport={handleExport} 
            exportStatus={exportStatus} 
            handleAudioUpload={handleAudioUpload} 
            handleLyricsUpload={(f) => {}} 
            currentTime={currentTime} 
          />
        </div>
      </main>
      {exportStatus.status !== 'idle' && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/90 backdrop-blur-md">
           <div className="glass p-10 rounded-[3rem] w-full max-w-md text-center space-y-8 shadow-2xl border-white/10">
            <div className="text-3xl font-black text-white tracking-tight">
              {exportStatus.status === 'completed' ? 'Success! 🎉' : 'Cinema AI Engine'}
            </div>
            {(exportStatus.status === 'generating' || exportStatus.status === 'idle') && (
              <div className="flex flex-col items-center gap-8">
                <div className="relative w-32 h-32">
                  <div className="absolute inset-0 border-4 border-pink-500/20 rounded-full animate-pulse"></div>
                  <div className="absolute inset-0 border-4 border-pink-500 rounded-full border-t-transparent animate-spin"></div>
                  <div className="absolute inset-0 flex items-center justify-center text-pink-500 text-2xl font-black">{exportStatus.progress}%</div>
                </div>
                <div className="text-slate-300 text-sm font-bold uppercase tracking-widest">{exportStatus.message}</div>
              </div>
            )}
            {exportStatus.status === 'completed' && (
              <div className="space-y-6">
                <div className="w-20 h-20 bg-green-500/20 text-green-500 rounded-full flex items-center justify-center mx-auto text-4xl">
                  <i className="fa-solid fa-check"></i>
                </div>
                <p className="text-slate-300 font-medium">Your cinematic Telugu reel has been rendered and saved to your device.</p>
                <button onClick={() => setExportStatus(prev => ({ ...prev, status: 'idle' }))} className="w-full py-5 rounded-2xl bg-gradient-to-r from-pink-600 to-violet-600 font-black text-white uppercase tracking-widest hover:scale-[1.02] transition-all">Continue Creating</button>
              </div>
            )}
           </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useRef, useEffect } from 'react';
import { ReelState, ReelMedia, TransitionType } from '../types';

interface PreviewCanvasProps {
  state: ReelState;
  currentTime: number;
  isPlaying: boolean;
}

const PreviewCanvas: React.FC<PreviewCanvasProps> = ({ state, currentTime, isPlaying }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const imageCache = useRef<Map<string, HTMLImageElement>>(new Map());
  const videoCache = useRef<Map<string, HTMLVideoElement>>(new Map());

  const loadImage = (src: string): Promise<HTMLImageElement> => {
    if (imageCache.current.has(src)) return Promise.resolve(imageCache.current.get(src)!);
    return new Promise((resolve) => {
      const img = new Image();
      img.onload = () => {
        imageCache.current.set(src, img);
        resolve(img);
      };
      img.src = src;
    });
  };

  const loadVideo = (src: string): Promise<HTMLVideoElement> => {
    if (videoCache.current.has(src)) return Promise.resolve(videoCache.current.get(src)!);
    return new Promise((resolve) => {
      const video = document.createElement('video');
      video.src = src;
      video.muted = true;
      video.loop = false;
      video.playsInline = true;
      video.onloadedmetadata = () => {
        videoCache.current.set(src, video);
        resolve(video);
      };
    });
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const render = async () => {
      const { width, height } = canvas;
      ctx.clearRect(0, 0, width, height);

      // 1. Draw Background Media Transitions
      if (state.images.length > 0) {
        let accumulatedTime = 0;
        let activeIndex = 0;
        for (let i = 0; i < state.images.length; i++) {
          const nextAccumulated = accumulatedTime + state.images[i].duration;
          if (currentTime < nextAccumulated) {
            activeIndex = i;
            break;
          }
          accumulatedTime = nextAccumulated;
        }

        const currentMedia = state.images[activeIndex];
        const nextMediaIndex = (activeIndex + 1) % state.images.length;
        const nextMedia = state.images[nextMediaIndex];

        const timeInCurrentSlide = currentTime - accumulatedTime;
        const progressInSlide = timeInCurrentSlide / currentMedia.duration;
        const transitionDuration = 0.8;
        const transitionThreshold = Math.max(0, currentMedia.duration - transitionDuration) / currentMedia.duration;

        const drawMediaCover = async (
          media: ReelMedia, 
          alpha: number, 
          scale: number = 1, 
          offsetX: number = 0, 
          offsetY: number = 0,
          blur: number = 0,
          mediaTime: number = 0
        ) => {
          ctx.save();
          ctx.globalAlpha = alpha;
          if (blur > 0) ctx.filter = `blur(${blur}px)`;

          let source: CanvasImageSource;
          let sWidth, sHeight;

          if (media.type === 'video') {
            const video = await loadVideo(media.url);

            // SMART SYNC LOGIC:
            // Only seek if the drift is more than 150ms to prevent stuttering/sticking
            const desiredTime = mediaTime % (media.originalDuration || video.duration);
            if (Math.abs(video.currentTime - desiredTime) > 0.15) {
              video.currentTime = desiredTime;
            }

            // Sync playback state with app state
            if (isPlaying && video.paused) {
              video.play().catch(() => {});
            } else if (!isPlaying && !video.paused) {
              video.pause();
            }

            source = video;
            sWidth = video.videoWidth;
            sHeight = video.videoHeight;
          } else {
            const img = await loadImage(media.url);
            source = img;
            sWidth = img.width;
            sHeight = img.height;
          }

          const ratio = Math.max(width / sWidth, height / sHeight);
          const w = sWidth * ratio * scale;
          const h = sHeight * ratio * scale;
          const x = (width - w) / 2 + offsetX;
          const y = (height - h) / 2 + offsetY;

          ctx.drawImage(source, x, y, w, h);
          ctx.restore();
        };

        const transition = currentMedia.transition || 'fade';

        // Clean up: Pause all videos that are NOT the active index to save resources
        videoCache.current.forEach((video, url) => {
          if (url !== currentMedia.url && !video.paused) {
            video.pause();
          }
        });

        if (progressInSlide > transitionThreshold && state.images.length > 1) {
          const t = (progressInSlide - transitionThreshold) / (1 - transitionThreshold); 

          if (transition === 'fade') {
            await drawMediaCover(currentMedia, 1 - t, 1, 0, 0, 0, timeInCurrentSlide);
            await drawMediaCover(nextMedia, t, 1, 0, 0, 0, 0);
          } else if (transition === 'zoom-in') {
            await drawMediaCover(currentMedia, 1 - t, 1 + t * 0.2, 0, 0, 0, timeInCurrentSlide);
            await drawMediaCover(nextMedia, t, 0.8 + t * 0.2, 0, 0, 0, 0);
          } else if (transition === 'zoom-out') {
            await drawMediaCover(currentMedia, 1 - t, 1 - t * 0.2, 0, 0, 0, timeInCurrentSlide);
            await drawMediaCover(nextMedia, t, 1.2 - t * 0.2, 0, 0, 0, 0);
          } else if (transition === 'slide-left') {
            await drawMediaCover(currentMedia, 1, 1, -t * width, 0, 0, timeInCurrentSlide);
            await drawMediaCover(nextMedia, 1, 1, width - t * width, 0, 0, 0);
          } else if (transition === 'slide-right') {
            await drawMediaCover(currentMedia, 1, 1, t * width, 0, 0, timeInCurrentSlide);
            await drawMediaCover(nextMedia, 1, 1, -width + t * width, 0, 0, 0);
          } else if (transition === 'blur') {
            await drawMediaCover(currentMedia, 1 - t, 1, 0, 0, t * 20, timeInCurrentSlide);
            await drawMediaCover(nextMedia, t, 1, 0, 0, (1 - t) * 20, 0);
          }
        } else {
          await drawMediaCover(currentMedia, 1, 1, 0, 0, 0, timeInCurrentSlide);
        }
      } else {
        ctx.fillStyle = '#0f172a';
        ctx.fillRect(0, 0, width, height);
      }

      // 2. Logo Overlay
      if (state.logo) {
        const logoImg = await loadImage(state.logo);
        ctx.save();
        ctx.globalAlpha = 1.0;
        const lx = (width * state.logoPosition.x) / 100;
        const ly = (height * state.logoPosition.y) / 100;
        const lSize = state.logoPosition.size;
        ctx.drawImage(logoImg, lx - lSize/2, ly - lSize/2, lSize, lSize);
        ctx.restore();
      }

      // 3. Watermark
      if (state.watermark.text) {
        ctx.save();
        ctx.globalAlpha = state.watermark.opacity;
        ctx.fillStyle = state.watermark.color;
        ctx.font = `bold ${state.watermark.size}px Inter`;
        ctx.textAlign = state.watermark.textAlign;

        const wx = (width * state.watermark.x) / 100;
        const wy = (height * state.watermark.y) / 100;
        ctx.fillText(state.watermark.text.toUpperCase(), wx, wy);
        ctx.restore();
      }

      // 4. Lyrics Engine
      const activeLyric = state.lyrics.find(l => currentTime >= l.startTime && currentTime <= l.endTime);
      if (activeLyric) {
        const { lyricStyle } = state;
        const fontStr = `bold ${lyricStyle.fontSize}px "${lyricStyle.fontFamily}", sans-serif`;
        try { await document.fonts.load(fontStr); } catch (e) {}

        const animDuration = 0.5;
        const segmentTime = currentTime - activeLyric.startTime;

        let alpha = 1;
        let scale = 1;
        let yOffset = 0;
        let rotation = 0;
        let charLimit = activeLyric.text.length;

        if (segmentTime < animDuration) {
          const t = segmentTime / animDuration;
          if (lyricStyle.animation === 'fade') alpha = t;
          else if (lyricStyle.animation === 'slide-up') { yOffset = (1 - t) * 60; alpha = t; }
          else if (lyricStyle.animation === 'scale') { scale = 0.5 + (t * 0.5); alpha = t; }
          else if (lyricStyle.animation === 'typewriter') charLimit = Math.floor(t * activeLyric.text.length);
          else if (lyricStyle.animation === 'rotate') { rotation = (1 - t) * Math.PI / 4; alpha = t; scale = 0.5 + (t * 0.5); }
        }

        if (lyricStyle.animation === 'float') yOffset += Math.sin(currentTime * 3) * 20;
        else if (lyricStyle.animation === 'bounce') yOffset += Math.abs(Math.sin(currentTime * 5)) * -40;
        else if (lyricStyle.animation === 'glow-pulse') {
          const pulse = (Math.sin(currentTime * 6) + 1) / 2;
          ctx.shadowBlur = lyricStyle.glowIntensity * (0.8 + pulse * 0.4);
        }

        ctx.save();
        ctx.globalAlpha = alpha;

        if (lyricStyle.glowIntensity > 0) {
          ctx.shadowColor = lyricStyle.glowColor;
          ctx.shadowBlur = lyricStyle.glowIntensity;
        } else if (lyricStyle.shadow) {
          ctx.shadowColor = 'rgba(0,0,0,0.85)';
          ctx.shadowBlur = 15;
          ctx.shadowOffsetY = 6;
        }

        ctx.font = fontStr;
        ctx.textAlign = lyricStyle.textAlign;

        const displayText = lyricStyle.animation === 'typewriter' ? activeLyric.text.slice(0, charLimit) : activeLyric.text;
        const lines = [];
        const words = displayText.split(' ');
        let currentLine = '';
        for (let word of words) {
          const test = currentLine + word + ' ';
          if (ctx.measureText(test).width > width - 120) {
            lines.push(currentLine.trim());
            currentLine = word + ' ';
          } else {
            currentLine = test;
          }
        }
        lines.push(currentLine.trim());

        const baseLineHeight = lyricStyle.fontSize * lyricStyle.lineGap;
        const startY = (height * lyricStyle.verticalPosition / 100) + yOffset;
        const startX = lyricStyle.textAlign === 'center' ? width / 2 : (lyricStyle.textAlign === 'left' ? 60 : width - 60);

        ctx.translate(startX, startY);
        ctx.scale(scale, scale);
        ctx.rotate(rotation);
        ctx.translate(-startX, -startY);

        lines.forEach((l, i) => {
          const lineY = startY + (i * baseLineHeight);
          if (lyricStyle.stroke) {
            ctx.strokeStyle = lyricStyle.strokeColor;
            ctx.lineWidth = lyricStyle.strokeWidth;
            ctx.strokeText(l, startX, lineY);
          }
          if (lyricStyle.gradient) {
            const grad = ctx.createLinearGradient(startX - 200, lineY - 60, startX + 200, lineY + 60);
            grad.addColorStop(0, lyricStyle.gradientColors[0]);
            grad.addColorStop(1, lyricStyle.gradientColors[1]);
            ctx.fillStyle = grad;
          } else {
            ctx.fillStyle = lyricStyle.color;
          }
          ctx.fillText(l, startX, lineY);
        });
        ctx.restore();
      }
    };

    render();
  }, [state, currentTime, isPlaying]);

  return <canvas id="reel-preview-canvas" ref={canvasRef} width={1080} height={1920} className="w-full h-full object-cover" />;
};

export default PreviewCanvas;

export interface LyricSegment {
  text: string;
  startTime: number; // in seconds
  endTime: number;
}

export type TransitionType = 'fade' | 'zoom-in' | 'zoom-out' | 'slide-left' | 'slide-right' | 'blur';
export type MediaType = 'image' | 'video';

export interface ReelMedia {
  url: string;
  type: MediaType;
  duration: number;
  transition: TransitionType;
  originalDuration?: number;
  audioEnabled: boolean; // New: toggle video audio
  volume: number;       // New: video audio volume (0-1)
}

export interface VolumeHighlight {
  id: string;
  start: number;
  end: number;
  volume: number; // Multiplier, e.g., 1.5 for 150%
}

export type LyricAnimation = 'none' | 'fade' | 'slide-up' | 'scale' | 'typewriter' | 'glow-pulse' | 'float' | 'bounce' | 'rotate';

export interface LyricStyle {
  fontFamily: string;
  fontSize: number;
  lineGap: number;
  color: string;
  animation: LyricAnimation;
  verticalPosition: number; // 0 to 100 (percentage from top)
  textAlign: 'left' | 'center' | 'right';
  shadow: boolean;
  glowColor: string;
  glowIntensity: number;
  gradient: boolean;
  gradientColors: [string, string];
  stroke: boolean;
  strokeColor: string;
  strokeWidth: number;
}

export interface ReelState {
  images: ReelMedia[];
  logo: string | null;
  logoPosition: { x: number; y: number; size: number };
  audioUrl: string | null;
  audioName: string | null;
  audioDuration: number;
  audioTrim: {
    start: number;
    end: number;
  };
  musicVolume: number; // Global background music base volume
  musicHighlights: VolumeHighlight[]; // New: sections to boost music
  lyrics: LyricSegment[];
  lyricStyle: LyricStyle;
  watermark: {
    text: string;
    color: string;
    size: number;
    opacity: number;
    x: number; // 0 to 100
    y: number; // 0 to 100
    textAlign: 'left' | 'center' | 'right';
  };
  songTitle: string;
}

export interface ExportStatus {
  progress: number;
  status: 'idle' | 'generating' | 'completed' | 'error';
  message: string;
}

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { ReelState, LyricSegment, ExportStatus, ReelMedia, VolumeHighlight } from './types';
import { GeminiService } from './services/geminiService';
import EditorPanel from './components/EditorPanel';
import PreviewCanvas from './components/PreviewCanvas';
import Header from './components/Header';

const App: React.FC = () => {
  const [state, setState] = useState<ReelState>({
    images: [],
    logo: null,
    logoPosition: { x: 85, y: 10, size: 120 },
    audioUrl: null,
    audioName: null,
    audioDuration: 0,
    audioTrim: { start: 0, end: 15 },
    musicVolume: 0.8,
    musicHighlights: [],
    lyrics: [],
    lyricStyle: {
      fontFamily: 'Ramabhadra',
      fontSize: 84,
      lineGap: 1.3,
      color: '#ffffff',
      animation: 'slide-up',
      verticalPosition: 50,
      textAlign: 'center',
      shadow: true,
      glowColor: '#ec4899',
      glowIntensity: 20,
      gradient: true,
      gradientColors: ['#ffffff', '#f472b6'],
      stroke: true,
      strokeColor: '#000000',
      strokeWidth: 5
    },
    watermark: {
      text: 'Created with ReelGenius',
      color: '#ffffff',
      size: 28,
      opacity: 0.7,
      x: 50,
      y: 90,
      textAlign: 'center'
    },
    songTitle: ''
  });

  const [exportStatus, setExportStatus] = useState<ExportStatus>({
    progress: 0,
    status: 'idle',
    message: ''
  });

  const [isPlaying, setIsPlaying] = useState(false);
  const [isExporting, setIsExporting] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const recordedChunksRef = useRef<Blob[]>([]);

  // Audio Context for mixing
  const audioCtxRef = useRef<AudioContext | null>(null);
  const musicGainNodeRef = useRef<GainNode | null>(null);

  const gemini = GeminiService.getInstance();

  const totalDuration = useMemo(() => {
    return state.images.reduce((acc, img) => acc + img.duration, 0) || 0.1;
  }, [state.images]);

  const handleMediaUpload = async (files: FileList | null) => {
    if (!files) return;
    const filesArray = Array.from(files);
    const newMediaItems: ReelMedia[] = [];

    for (const file of filesArray) {
      if (file.type.startsWith('image/')) {
        const reader = new FileReader();
        const promise = new Promise<void>((resolve) => {
          reader.onload = (e) => {
            if (e.target?.result) {
              newMediaItems.push({ 
                url: e.target.result as string, 
                type: 'image',
                duration: 3,
                transition: 'zoom-in',
                audioEnabled: false,
                volume: 1.0
              });
            }
            resolve();
          };
          reader.readAsDataURL(file);
        });
        await promise;
      } else if (file.type.startsWith('video/')) {
        const url = URL.createObjectURL(file);
        const tempVideo = document.createElement('video');
        tempVideo.src = url;
        const promise = new Promise<void>((resolve) => {
          tempVideo.onloadedmetadata = () => {
            const vidDuration = tempVideo.duration;
            newMediaItems.push({
              url: url,
              type: 'video',
              duration: vidDuration,
              originalDuration: vidDuration,
              transition: 'fade',
              audioEnabled: true,
              volume: 1.0
            });
            resolve();
          };
        });
        await promise;
      }
    }

    setState(prev => ({ ...prev, images: [...prev.images, ...newMediaItems] }));
  };

  const handleAudioUpload = (file: File | null) => {
    if (!file) return;
    const url = URL.createObjectURL(file);
    const tempAudio = new Audio(url);
    tempAudio.onloadedmetadata = () => {
      setState(prev => ({ 
        ...prev, 
        audioUrl: url, 
        audioName: file.name,
        audioDuration: tempAudio.duration,
        audioTrim: { start: 0, end: Math.min(tempAudio.duration, totalDuration) }
      }));
      if (audioRef.current) audioRef.current.src = url;
    };
  };

  const generateLyrics = async () => {
    if (!state.songTitle) return;
    setExportStatus({ status: 'generating', progress: 10, message: 'AI is thinking of Telugu lyrics...', });
    try {
      const lyrics = await gemini.generateLyricsTimestamps(state.songTitle, totalDuration);
      setState(prev => ({ ...prev, lyrics }));
      setExportStatus({ status: 'idle', progress: 0, message: '' });
    } catch (err) {
      setExportStatus({ status: 'error', progress: 0, message: 'Failed to generate Telugu lyrics' });
    }
  };

  const handleExport = async () => {
    if (state.images.length === 0) return;
    setIsExporting(true);
    setExportStatus({ status: 'generating', progress: 0, message: 'Preparing high-def recorder...' });

    setCurrentTime(0);
    recordedChunksRef.current = [];

    const canvas = document.getElementById('reel-preview-canvas') as HTMLCanvasElement;
    if (!canvas) {
      setExportStatus({ status: 'error', progress: 0, message: 'Canvas engine not found.' });
      return;
    }

    const stream = canvas.captureStream(30); 

    // Mix the audio stream
    if (audioCtxRef.current) {
        const dest = audioCtxRef.current.createMediaStreamDestination();
        // If we want to record the mixed audio, we'd need to connect our gain nodes here.
        // For simplicity in this browser environment, we'll try to capture the destination stream.
        musicGainNodeRef.current?.connect(dest);

        const mixedAudioTrack = dest.stream.getAudioTracks()[0];
        if (mixedAudioTrack) stream.addTrack(mixedAudioTrack);
    }

    const recorder = new MediaRecorder(stream, { mimeType: 'video/webm;codecs=vp9,opus' });
    recorder.ondataavailable = (e) => { if (e.data.size > 0) recordedChunksRef.current.push(e.data); };
    recorder.onstop = () => {
      const blob = new Blob(recordedChunksRef.current, { type: 'video/webm' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `telugu-reel-${Date.now()}.webm`;
      a.click();
      setExportStatus({ status: 'completed', progress: 100, message: 'Cinema-quality Reel downloaded!' });
      setIsExporting(false);
      setIsPlaying(false);
    };

    mediaRecorderRef.current = recorder;
    recorder.start();
    setIsPlaying(true);
  };

  // Initialize Audio Context on first interaction
  const initAudio = () => {
    if (!audioCtxRef.current) {
      audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      if (audioRef.current) {
        const source = audioCtxRef.current.createMediaElementSource(audioRef.current);
        const gainNode = audioCtxRef.current.createGain();
        source.connect(gainNode).connect(audioCtxRef.current.destination);
        musicGainNodeRef.current = gainNode;
      }
    }
  };

  // Synchronize Audio Playback and Highlights
  useEffect(() => {
    if (isPlaying) {
      initAudio();
      if (audioRef.current) {
        audioRef.current.currentTime = state.audioTrim.start + currentTime;
        audioRef.current.play().catch(() => {});
      }
    } else {
      if (audioRef.current) audioRef.current.pause();
    }
  }, [isPlaying]);

  // Handle Dynamic Volume Highlighting
  useEffect(() => {
    if (!musicGainNodeRef.current) return;

    // Find if current time falls in a highlight zone
    const activeHighlight = state.musicHighlights.find(h => currentTime >= h.start && currentTime <= h.end);
    const targetVolume = activeHighlight ? state.musicVolume * activeHighlight.volume : state.musicVolume;

    // Smoothly transition volume to prevent pops
    musicGainNodeRef.current.gain.setTargetAtTime(targetVolume, audioCtxRef.current?.currentTime || 0, 0.1);
  }, [currentTime, state.musicVolume, state.musicHighlights]);

  useEffect(() => {
    let interval: any;
    if (isPlaying) {
      interval = setInterval(() => {
        setCurrentTime(prev => {
          const nextTime = prev + 0.05;
          if (isExporting) {
             const progress = Math.min(100, Math.floor((nextTime / totalDuration) * 100));
             setExportStatus(s => ({ ...s, progress, message: `Capturing frames: ${progress}%` }));
          }
          if (nextTime >= totalDuration) {
            setIsPlaying(false);
            if (audioRef.current) audioRef.current.pause();
            if (isExporting && mediaRecorderRef.current) mediaRecorderRef.current.stop();
            return totalDuration;
          }
          return nextTime;
        });
      }, 50);
    }
    return () => clearInterval(interval);
  }, [isPlaying, totalDuration, isExporting]);

  return (
    <div className="min-h-screen flex flex-col">
      <Header />
      <audio ref={audioRef} className="hidden" src={state.audioUrl || ''} crossOrigin="anonymous" />
      <main className="flex-1 flex flex-col md:flex-row p-4 gap-6 max-w-7xl mx-auto w-full overflow-hidden">
        <div className="flex-1 flex flex-col items-center justify-center space-y-4">
          <div className="relative aspect-[9/16] w-full max-w-[340px] bg-black rounded-3xl overflow-hidden shadow-2xl border-4 border-slate-800 group">
            <PreviewCanvas state={state} currentTime={currentTime} isPlaying={isPlaying} />
            <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity bg-black/30">
              {!isExporting && (
                <button onClick={() => { initAudio(); setIsPlaying(!isPlaying); }} className="w-16 h-16 rounded-full bg-white/20 backdrop-blur-md border border-white/30 flex items-center justify-center hover:bg-white/40 transition-all transform active:scale-95 shadow-xl">
                  <i className={`fa-solid ${isPlaying ? 'fa-pause' : 'fa-play'} text-white text-2xl`}></i>
                </button>
              )}
            </div>
            {isExporting && (
               <div className="absolute top-4 left-4 flex items-center gap-2 bg-red-600 px-3 py-1 rounded-full animate-pulse shadow-lg">
                 <div className="w-2 h-2 bg-white rounded-full"></div>
                 <span className="text-[10px] font-black text-white uppercase tracking-widest">RECORDING LIVE</span>
               </div>
            )}
            <div className="absolute bottom-4 left-4 right-4 h-1.5 bg-white/10 rounded-full overflow-hidden backdrop-blur-sm">
               <div className="h-full bg-gradient-to-r from-pink-500 to-violet-500 transition-all duration-100 ease-linear" style={{ width: `${(currentTime / totalDuration) * 100}%` }} />
            </div>
          </div>
          <div className="flex gap-4">
             <button disabled={isExporting} onClick={() => { initAudio(); setIsPlaying(!isPlaying); }} className={`px-8 py-3 rounded-full font-bold transition-all flex items-center gap-2 ${isPlaying ? 'bg-slate-700 text-white' : 'bg-pink-600 text-white hover:bg-pink-500 shadow-lg shadow-pink-500/30'} disabled:opacity-50`}>
               <i className={`fa-solid ${isPlaying ? 'fa-pause' : 'fa-play'}`}></i> {isPlaying ? 'PAUSE' : 'PLAY REEL'}
             </button>
             <button disabled={isExporting} onClick={() => { setCurrentTime(0); if (audioRef.current) audioRef.current.currentTime = state.audioTrim.start; }} className="px-6 py-3 rounded-full bg-slate-800 text-slate-300 hover:bg-slate-700 font-bold border border-slate-700 disabled:opacity-50">
               <i className="fa-solid fa-rotate-left mr-2"></i> RESTART
             </button>
          </div>
        </div>
        <div className="w-full md:w-[420px] lg:w-[520px] h-[calc(100vh-140px)]">
          <EditorPanel 
            state={state} 
            setState={setState} 
            handleImageUpload={handleMediaUpload} 
            generateLyrics={generateLyrics} 
            handleExport={handleExport} 
            exportStatus={exportStatus} 
            handleAudioUpload={handleAudioUpload} 
            handleLyricsUpload={(f) => {}} 
            currentTime={currentTime} 
          />
        </div>
      </main>
      {exportStatus.status !== 'idle' && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/90 backdrop-blur-md">
           <div className="glass p-10 rounded-[3rem] w-full max-w-md text-center space-y-8 shadow-2xl border-white/10">
            <div className="text-3xl font-black text-white tracking-tight">
              {exportStatus.status === 'completed' ? 'Success! 🎉' : 'Cinema AI Engine'}
            </div>
            {(exportStatus.status === 'generating' || exportStatus.status === 'idle') && (
              <div className="flex flex-col items-center gap-8">
                <div className="relative w-32 h-32">
                  <div className="absolute inset-0 border-4 border-pink-500/20 rounded-full animate-pulse"></div>
                  <div className="absolute inset-0 border-4 border-pink-500 rounded-full border-t-transparent animate-spin"></div>
                  <div className="absolute inset-0 flex items-center justify-center text-pink-500 text-2xl font-black">{exportStatus.progress}%</div>
                </div>
                <div className="text-slate-300 text-sm font-bold uppercase tracking-widest">{exportStatus.message}</div>
              </div>
            )}
            {exportStatus.status === 'completed' && (
              <div className="space-y-6">
                <div className="w-20 h-20 bg-green-500/20 text-green-500 rounded-full flex items-center justify-center mx-auto text-4xl">
                  <i className="fa-solid fa-check"></i>
                </div>
                <p className="text-slate-300 font-medium">Your cinematic Telugu reel has been rendered and saved to your device.</p>
                <button onClick={() => setExportStatus(prev => ({ ...prev, status: 'idle' }))} className="w-full py-5 rounded-2xl bg-gradient-to-r from-pink-600 to-violet-600 font-black text-white uppercase tracking-widest hover:scale-[1.02] transition-all">Continue Creating</button>
              </div>
            )}
           </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { ReelState, ExportStatus, LyricSegment, ReelMedia, LyricAnimation, TransitionType, VolumeHighlight } from '../types';

interface EditorPanelProps {
  state: ReelState;
  setState: React.Dispatch<React.SetStateAction<ReelState>>;
  handleImageUpload: (files: FileList | null) => void;
  handleAudioUpload: (file: File | null) => void;
  handleLyricsUpload: (file: File | null) => void;
  generateLyrics: () => void;
  handleExport: () => void;
  exportStatus: ExportStatus;
  currentTime: number;
}

const EditorPanel: React.FC<EditorPanelProps> = ({
  state,
  setState,
  handleImageUpload,
  handleAudioUpload,
  handleLyricsUpload,
  generateLyrics,
  handleExport,
  exportStatus,
  currentTime
}) => {
  const [activeTab, setActiveTab] = useState<'content' | 'lyrics' | 'style' | 'branding'>('content');

  const totalReelDuration = useMemo(() => {
    return state.images.reduce((acc, img) => acc + img.duration, 0) || 0;
  }, [state.images]);

  const updateImage = (index: number, updates: Partial<ReelMedia>) => {
    setState(prev => {
      const nextImages = [...prev.images];
      nextImages[index] = { ...nextImages[index], ...updates };
      return { ...prev, images: nextImages };
    });
  };

  const updateLyric = (index: number, updates: Partial<LyricSegment>) => {
    setState(prev => {
      const next = [...prev.lyrics];
      next[index] = { ...next[index], ...updates };
      return { ...prev, lyrics: next };
    });
  };

  const updateLyricStyle = (updates: Partial<typeof state.lyricStyle>) => {
    setState(prev => ({
      ...prev,
      lyricStyle: { ...prev.lyricStyle, ...updates }
    }));
  };

  const updateWatermark = (updates: Partial<typeof state.watermark>) => {
    setState(prev => ({
      ...prev,
      watermark: { ...prev.watermark, ...updates }
    }));
  };

  const updateLogoPosition = (updates: Partial<typeof state.logoPosition>) => {
    setState(prev => ({
      ...prev,
      logoPosition: { ...prev.logoPosition, ...updates }
    }));
  };

  const addVolumeHighlight = () => {
    const newHighlight: VolumeHighlight = {
      id: Math.random().toString(36).substr(2, 9),
      start: currentTime,
      end: Math.min(currentTime + 3, totalReelDuration),
      volume: 1.5
    };
    setState(prev => ({ ...prev, musicHighlights: [...prev.musicHighlights, newHighlight] }));
  };

  const updateHighlight = (id: string, updates: Partial<VolumeHighlight>) => {
    setState(prev => ({
      ...prev,
      musicHighlights: prev.musicHighlights.map(h => h.id === id ? { ...h, ...updates } : h)
    }));
  };

  const teluguFonts = ['Hind Guntur', 'Ramabhadra', 'Gidugu', 'Gurajada', 'Suranna', 'NTR', 'Tenali Ramakrishna'];
  const latinFonts = ['Inter', 'Montserrat', 'Pacifico', 'Bungee', 'Playfair Display', 'Space Mono'];

  const animations: { label: string; value: LyricAnimation; icon: string }[] = [
    { label: 'None', value: 'none', icon: 'fa-slash' },
    { label: 'Fade', value: 'fade', icon: 'fa-eye' },
    { label: 'Slide', value: 'slide-up', icon: 'fa-arrow-up' },
    { label: 'Zoom', value: 'scale', icon: 'fa-expand' },
    { label: 'Type', value: 'typewriter', icon: 'fa-keyboard' },
    { label: 'Neon', value: 'glow-pulse', icon: 'fa-bolt' },
    { label: 'Float', value: 'float', icon: 'fa-cloud' },
    { label: 'Bounce', value: 'bounce', icon: 'fa-baseball-ball' },
    { label: 'Rotate', value: 'rotate', icon: 'fa-sync-alt' },
  ];

  const transitions: { label: string; value: TransitionType }[] = [
    { label: 'Fade Out', value: 'fade' },
    { label: 'Zoom In', value: 'zoom-in' },
    { label: 'Zoom Out', value: 'zoom-out' },
    { label: 'Slide Left', value: 'slide-left' },
    { label: 'Slide Right', value: 'slide-right' },
    { label: 'Blur', value: 'blur' },
  ];

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    const ms = Math.floor((seconds % 1) * 10);
    return `${mins}:${secs.toString().padStart(2, '0')}.${ms}`;
  };

  const maxStartTime = Math.max(0, state.audioDuration - totalReelDuration);

  return (
    <div className="h-full flex flex-col glass rounded-[2.5rem] border-slate-800/50 shadow-2xl overflow-hidden">
      <div className="flex p-2 bg-slate-900/50 border-b border-slate-800">
        {[
          { id: 'content', icon: 'fa-images' },
          { id: 'lyrics', icon: 'fa-clock' },
          { id: 'style', icon: 'fa-wand-magic-sparkles' },
          { id: 'branding', icon: 'fa-copyright' }
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex-1 py-3 rounded-2xl flex flex-col items-center gap-1 transition-all ${
              activeTab === tab.id ? 'bg-pink-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'
            }`}
          >
            <i className={`fa-solid ${tab.icon} text-sm`}></i>
            <span className="text-[9px] font-black uppercase tracking-tighter">{tab.id}</span>
          </button>
        ))}
      </div>

      <div className="flex-1 overflow-y-auto p-7 space-y-8 custom-scrollbar">
        {activeTab === 'content' && (
          <div className="space-y-6 animate-in fade-in duration-300">
            <section className="space-y-4">
              <h3 className="text-sm font-black uppercase tracking-widest text-pink-500">Timeline & Mixing</h3>
              <div className="space-y-4">
                {state.images.map((media, idx) => (
                  <div key={idx} className="bg-slate-900/40 rounded-3xl p-5 border border-slate-800/50 group space-y-4 transition-all hover:bg-slate-800/40">
                    <div className="flex gap-4 items-center">
                        <div className="w-20 aspect-[4/5] rounded-xl overflow-hidden relative shrink-0 shadow-lg">
                        {media.type === 'video' ? (
                            <video src={media.url} className="w-full h-full object-cover" />
                        ) : (
                            <img src={media.url} className="w-full h-full object-cover" />
                        )}
                        <button onClick={() => setState(prev => ({ ...prev, images: prev.images.filter((_, i) => i !== idx) }))} className="absolute inset-0 bg-red-500/80 text-white opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center"><i className="fa-solid fa-trash-can"></i></button>
                        <div className="absolute top-1 left-1 bg-black/50 px-1.5 py-0.5 rounded text-[8px] font-bold uppercase text-white backdrop-blur-sm">
                            {media.type}
